--
-- Name: report_all_channels_sales; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.report_all_channels_sales AS
 SELECT foo.id,
    foo.name,
    foo.partner_id,
    foo.product_id,
    foo.product_tmpl_id,
    foo.date_order,
    foo.user_id,
    foo.categ_id,
    foo.company_id,
    foo.price_total,
    foo.pricelist_id,
    foo.analytic_account_id,
    foo.country_id,
    foo.team_id,
    foo.price_subtotal,
    foo.product_qty
   FROM ( WITH currency_rate AS (
                 SELECT r.currency_id,
                    COALESCE(r.company_id, c.id) AS company_id,
                    r.rate,
                    r.name AS date_start,
                    ( SELECT r2.name
                           FROM public.res_currency_rate r2
                          WHERE ((r2.name > r.name) AND (r2.currency_id = r.currency_id) AND ((r2.company_id IS NULL) OR (r2.company_id = c.id)))
                          ORDER BY r2.name
                         LIMIT 1) AS date_end
                   FROM (public.res_currency_rate r
                     JOIN public.res_company c ON (((r.company_id IS NULL) OR (r.company_id = c.id))))
                )
         SELECT sol.id,
            so.name,
            so.partner_id,
            sol.product_id,
            pro.product_tmpl_id,
            so.date_order,
            so.user_id,
            pt.categ_id,
            so.company_id,
            (sol.price_total / COALESCE(cr.rate, 1.0)) AS price_total,
            so.pricelist_id,
            rp.country_id,
            (sol.price_subtotal / COALESCE(cr.rate, 1.0)) AS price_subtotal,
            ((sol.product_uom_qty / u.factor) * u2.factor) AS product_qty,
            so.analytic_account_id,
            so.team_id
           FROM ((((((((public.sale_order_line sol
             JOIN public.sale_order so ON ((sol.order_id = so.id)))
             LEFT JOIN public.product_product pro ON ((sol.product_id = pro.id)))
             JOIN public.res_partner rp ON ((so.partner_id = rp.id)))
             LEFT JOIN public.product_template pt ON ((pro.product_tmpl_id = pt.id)))
             LEFT JOIN public.product_pricelist pp ON ((so.pricelist_id = pp.id)))
             LEFT JOIN currency_rate cr ON (((cr.currency_id = pp.currency_id) AND (cr.company_id = so.company_id) AND (cr.date_start <= COALESCE((so.date_order)::timestamp with time zone, now())) AND ((cr.date_end IS NULL) OR (cr.date_end > COALESCE((so.date_order)::timestamp with time zone, now()))))))
             LEFT JOIN public.product_uom u ON ((u.id = sol.product_uom)))
             LEFT JOIN public.product_uom u2 ON ((u2.id = pt.uom_id)))
          WHERE ((so.state)::text <> 'cancel'::text)
        UNION ALL
         SELECT ('-1'::integer * pol.id) AS id,
            pos.name,
            pos.partner_id,
            pol.product_id,
            pro.product_tmpl_id,
            pos.date_order,
            pos.user_id,
            pt.categ_id,
            pos.company_id,
            (((pol.qty * pol.price_unit) * ((100)::numeric - pol.discount)) / (100)::numeric) AS price_total,
            pos.pricelist_id,
            rp.country_id,
            (pol.qty * pol.price_unit) AS price_subtotal,
            (pol.qty * u.factor) AS product_qty,
            NULL::integer AS analytic_account_id,
            config.crm_team_id AS team_id
           FROM (((((((((public.pos_order_line pol
             JOIN public.pos_order pos ON ((pos.id = pol.order_id)))
             LEFT JOIN public.pos_session session ON ((session.id = pos.session_id)))
             LEFT JOIN public.pos_config config ON ((config.id = session.config_id)))
             LEFT JOIN public.product_product pro ON ((pol.product_id = pro.id)))
             LEFT JOIN public.product_template pt ON ((pro.product_tmpl_id = pt.id)))
             LEFT JOIN public.product_category pc ON ((pt.categ_id = pc.id)))
             LEFT JOIN public.res_company rc ON ((pos.company_id = rc.id)))
             LEFT JOIN public.res_partner rp ON ((rc.partner_id = rp.id)))
             LEFT JOIN public.product_uom u ON ((u.id = pt.uom_id)))) foo;


