d name="vat" placeholder="e.g. BE0477472701" attrs="{'readonly': [('parent_id','!=',False)]}"/>\n                            <field name="category_id" widget="many2many_tags" options="{'color_field': 'color', 'no_create_edit': True}" placeholder="Tags..."/>\n                        </group>\n                        <group>\n                            <field name="function" placeholder="e.g. Sales Director" attrs="{'invisible': [('is_company','=', True)]}"/>\n                            <field name="phone" widget="phone"/>\n                            <field name="mobile" widget="phone"/>\n                            <field name="user_ids" invisible="1"/>\n                            <field name="email" widget="email" context="{'gravatar_image': True}" attrs="{'required': [('user_ids','!=', [])]}"/>\n                            <field name="website" widget="url" placeholder="e.g. www.odoo.com"/>\n                            <field name="title" options="{&quot;no_open&quot;: True}" attrs="{'invisible': [('is_company', '=', True)]}"/>\n                            <field name="lang"/>\n                        </group>\n                    </group>\n\n                    <notebook colspan="4">\n                        <page string="Contacts &amp; Addresses" autofocus="autofocus">\n                            <field name="child_ids" mode="kanban" context="{'default_parent_id': active_id, 'default_street': street, 'default_street2': street2, 'default_city': city, 'default_state_id': state_id, 'default_zip': zip, 'default_country_id': country_id, 'default_supplier': supplier, 'default_customer': customer, 'default_lang': lang,}">\n                                <kanban>\n                                    <field name="color"/>\n                                    <field name="name"/>\n                                    <field name="title"/>\n                                    <field name="type"/>\n                                    <field name="email"/>\n                                    <field name="parent_id"/>\n                                    <field name="is_company"/>\n                                    <field name="function"/>\n                                    <field name="phone"/>\n                                    <field name="street"/>\n                                    <field name="street2"/>\n                                    <field name="zip"/>\n                                    <field name="city"/>\n                                    <field name="country_id"/>\n                                    <field name="mobile"/>\n                                    <field name="state_id"/>\n                                    <field name="image_small"/>\n                                    <field name="lang"/>\n                                    <!-- fields in form x2many view to diminish requests -->\n                                    <field name="comment"/>\n                                    <field name="customer"/>\n                                    <field name="display_name"/>\n                                    <field name="supplier"/>\n                                    <templates>\n                                        <t t-name="kanban-box">\n                                            <t t-set="color" t-value="kanban_color(record.color.raw_value)"/>\n                                            <div t-att-class="color + (record.title.raw_value == 1 ? ' oe_kanban_color_alert' : '') + ' oe_kanban_global_click'">\n                                                <a t-if="!read_only_mode" type="delete" class="fa fa-times pull-right"/>\n                                                <div class="o_kanban_image">\n                                                    <img t-if="record.image_small.raw_value" t-att-src="'data:image/png;base64,'+record.image_small.raw_value"/>\n                                                    <t t-if="!record.image_small.raw_value">\n                                                        <img t-if="record.type.raw_value === 'delivery'" t-att-src="_s + &quot;/base/static/src/img/truck.png&quot;"/>\n                                                        <img t-if="record.type.raw_value === 'invoice'" t-att-src="_s + &quot;/base/static/src/img/money.png&quot;"/>\n                                                        <t t-if="record.type.raw_value !== 'invoice' &amp;&amp; record.type.raw_value !== 'delivery'">\n                                                            <img t-if="record.is_company.raw_value === true" t-att-src="_s + &quot;/base/static/src/img/company_image.png&quot;"/>\n                                                            <img t-if="record.is_company.raw_value === false" t-att-src="_s + &quot;/base/static/src/img/avatar.png&quot;"/>\n                                                        </t>\n                                                    </t>\n                                                </div>\n                                                <div class="oe_kanban_details">\n                                                    <field name="name"/>\n                                                    <div t-if="record.function.raw_value"><field name="function"/></div>\n                                                    <div t-if="record.email.raw_value"><field name="email" widget="email"/></div>\n                                                    <div t-if="record.type.raw_value != 'contact'">\n                                                        <div>\n                                                            <field name="zip"/>\n                                                            <field name="city"/>\n                                                        </div>\n                                                        <field t-if="record.state_id.raw_value" name="state_id"/>\n                                                        <field name="country_id"/>\n                                                    </div>\n                                                    <div t-if="record.phone.raw_value">Phone: <field name="phone"/></div>\n                                                    <div t-if="record.mobile.raw_value">Mobile: <field name="mobile"/></div>\n                                                </div>\n                                            </div>\n                                        </t>\n                                    </templates>\n                                </kanban>\n                                <form string="Contact / Address">\n                                    <sheet>\n                                        <!-- parent_id and type fields needed in attrs in base_address_city module which overwrites\n                                        _fields_view_get() of partner. It would be better to put those fields there but the web client\n                                        dosen't support when a field is displayed several times in the same view.-->\n                                        <field name="type" required="1" widget="radio" options="{'horizontal': true}"/>\n                                        <field name="parent_id" invisible="1"/>\n                                        <hr/>\n                                        <group>\n                                            <group attrs="{'invisible': [('type','=', 'contact')]}">\n                                                <label for="street" string="Address"/>\n                                                <div>\n                                                    <div class="o_address_format" name="div_address">\n                                                        <field name="street" placeholder="Street..." class="o_address_street"/>\n                                                        <field name="street2" placeholder="Street 2..." class="o_address_street"/>\n                                                        <field name="city" placeholder="City" class="o_address_city"/>\n                                                        <field name="state_id" class="o_address_state" placeholder="State" options="{&quot;no_open&quot;: True}" context="{'country_id': country_id, 'zip': zip}"/>\n                                                        <field name="zip" placeholder="ZIP" class="o_address_zip"/>\n                                                        <field name="country_id" placeholder="Country" class="o_address_country" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>\n                                                    </div>\n                                                </div>\n                                            </group>\n                                            <group>\n                                                <field name="name" string="Contact Name" attrs="{'required' : [('type', '=', 'contact')]}"/>\n                                                <field name="title" placeholder="e.g. Mr." attrs="{'invisible': [('type','!=', 'contact')]}"/>\n                                                <field name="function" placeholder="e.g. Sales Director" attrs="{'invisible': [('type','!=', 'contact')]}"/>\n                                                <field name="email"/>\n                                                <field name="phone" widget="phone"/>\n                                                <field name="mobile" widget="phone"/>\n                                                <field name="comment" placeholder="internal note..."/>\n                                            </group>\n                                        </group>\n                                        <field name="supplier" invisible="True"/>\n                                        <field name="customer" invisible="True"/>\n                                        <field name="lang" invisible="True"/>\n                                        <field name="image" invisible="True"/>\n                                    </sheet>\n                                </form>\n                            </field>\n                        </page>\n                        <page name="internal_notes" string="Internal Notes">\n                            <field name="comment" placeholder="Internal note..."/>\n                        </page>\n                        <page name="sales_purchases" string="Sales &amp; Purchases">\n                            <group name="container_row_2">\n                                <group string="Sale" name="sale">\n                                    <field name="customer"/>\n                                    <field name="user_id"/>\n                                </group>\n                                <group string="Purchase" name="purchase">\n                                    <field name="supplier"/>\n                                </group>\n                                <group string="Misc">\n                                    <field name="ref"/>\n                                    <field name="company_id" groups="base.group_multi_company" options="{'no_create': True}"/>\n                                    <field name="industry_id" attrs="{'invisible': [('is_company', '=', False)]}" options="{'no_create': True}"/>\n                                </group>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n                </form>\n            	base/res/res_partner_view.xml	\N	\N	2020-03-20 13:31:21.257828	2020-03-20 13:31:21.257828	primary	t	1	1
