169	web.qunit_mobile_suite	\N	web.qunit_mobile_suite	16	qweb	<?xml version="1.0"?>\n<t t-name="web.qunit_mobile_suite">\n        <t t-call="web.layout">\n            <t t-set="html_data" t-value="{'style': 'height: 100%;'}"/>\n            <t t-set="title">Web Mobile Tests</t>\n            <t t-set="head">\n                <script>\n                    // force the config.device.isMobile key to be true so that\n                    // mobile specific files aren't rejected\n                    window.odoo = {};\n                    var odooDefine;\n                    Object.defineProperty(window.odoo, 'define', {\n                        get: function () {\n                            return odooDefine;\n                        },\n                        set: function (define) {\n                            odooDefine = function () {\n                                define.apply(this, arguments);\n                                if (arguments[0] === 'web.config') {\n                                    define.call(this, 'web.config.patch', function (require) {\n                                        var config = require('web.config');\n                                        config.device.isMobile = true;\n                                    });\n                                }\n                            };\n                        },\n                    });\n                </script>\n\n                <t t-call="web.js_tests_assets"/>\n                <script type="text/javascript" src="/web/static/lib/jquery.touchSwipe/jquery.touchSwipe.js"/>\n\n                <script type="text/javascript" src="/web/static/tests/views/kanban_mobile_tests.js"/>\n            </t>\n\n            <div id="qunit"/>\n            <div id="qunit-fixture"/>\n        </t>\n    </t>\n\n    	web/views/webclient_templates.xml	\N	\N	2020-03-20 13:31:42.692413	2020-03-20 13:31:42.692413	primary	t	1	1
