171	web.webclient_bootstrap	\N	web.webclient_bootstrap	16	qweb	<?xml version="1.0"?>\n<t t-name="web.webclient_bootstrap">\n        <t t-call="web.layout">\n            <t t-set="head_web">\n                <script type="text/javascript">\n                    odoo.session_info = <t t-raw="session_info"/>;\n                </script>\n\n                <t t-call-assets="web.assets_common" t-js="false"/>\n                <t t-call-assets="web.assets_backend" t-js="false"/>\n                <t t-call-assets="web.assets_common" t-css="false"/>\n                <t t-call-assets="web.assets_backend" t-css="false"/>\n\n                \n                    &lt;!--[if lt IE 10]&gt;\n                        &lt;body class="ie9"&gt;\n                    &lt;![endif]--&gt;\n                \n\n                <script type="text/javascript">\n                    odoo.define('web.web_client', function (require) {\n                        var WebClient = require('web.WebClient');\n                        var web_client = new WebClient();\n                        $(function() {\n                            web_client.setElement($(document.body));\n                            web_client.start();\n                        });\n                        return web_client;\n                    });\n                </script>\n            </t>\n            <t t-set="head" t-value="head_web + (head or '')"/>\n            <t t-set="body_classname" t-value="'o_web_client'"/>\n\n            <nav id="oe_main_menu_navbar" class="navbar navbar-inverse" groups="base.group_user,base.group_portal">\n                <div class="navbar-header">\n                    <button type="button" class="navbar-toggle" data-toggle="collapse" data-target=".navbar-collapse">\n                        <span class="icon-bar"/>\n                        <span class="icon-bar"/>\n                        <span class="icon-bar"/>\n                    </button>\n                </div>\n                <div class="navbar-col