atic/lib/pdfjs/src/core/evaluator.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/cmap.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/fonts.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/font_renderer.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/glyphlist.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/image.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/metrics.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/parser.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/ps_parser.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/stream.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/worker.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/arithmetic_decoder.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/jpg.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/jpx.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/jbig2.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/bidi.js"/>\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/core/murmurhash3.js"/>\n        <!--\n            NOTE JEM : PDFJS not-minified load its assets dynamically. Not minify, this lib is huge (4000 lines).\n            To load PDFJS using odoo bundle, we create a custom worker_loader, to avoid reloading all the assets (core/*.js) dynamically.\n            Loading all this assets in a bundle can be problematic in debug mode, since we don't wait all assets to be loaded to start using PDFJS. That's why, in debug mode, we use the native loader, otherwise our custom loader is used.\n        -->\n        <t t-if="not debug">\n            <script>\n                // Use Odoo PDFJS Loader, to avoid dynamic assets loading\n                PDFJS.workerSrc = '/web/static/lib/pdfjs/worker_loader_by_odoo.js';\n                PDFJS.disableWorker = true;\n            </script>\n        </t>\n        <t t-if="debug">\n            <script>\n                // Specify the main script used to create a new PDF.JS web worker.\n                // In production, leave this undefined or change it to point to the\n                // combined `pdf.worker.js` file.\n                PDFJS.workerSrc = '/web/static/lib/pdfjs/src/worker_loader.js';\n            </script>\n        </t>\n        <!--\n            If no loader defined, this file will try to load pdf.worker.js (in build/).\n            It will crash since we don't use the minified version of PDFJS\n        -->\n        <script type="text/javascript" src="/web/static/lib/pdfjs/src/pdf.js"/>\n    </t>\n	web/views/webclient_templates.xml	\N	\N	2020-03-20 13:31:42.692413	2020-03-20 13:31:42.692413	primary	t	1	1
