178	minimal_layout	\N	web.minimal_layout	16	qweb	<?xml version="1.0"?>\n<t t-name="web.minimal_layout">\n        <t t-raw="'&lt;base href=%s&gt;' % base_url"/>\n        &lt;!DOCTYPE html&gt;\n        <html style="height: 0;">\n            <head>\n                <t t-call-assets="web.report_assets_pdf" t-js="false"/>\n                <t t-call-assets="web.report_assets_common" t-js="false"/>\n                <t t-call-assets="web.report_assets_pdf" t-css="false"/>\n                <t t-call-assets="web.report_assets_common" t-css="false"/>\n                <meta charset="utf-8"/>\n                <t t-if="subst is True">\n                    <script>\n                        function subst() {\n                            var vars = {};\n                            var x = document.location.search.substring(1).split('&amp;');\n                            for (var i in x) {\n                                var z = x[i].split('=', 2);\n                                vars[z[0]] = unescape(z[1]);\n                            }\n                            var fromPage = document.getElementsByClassName('page');\n                            for(var j = 0; j&lt;fromPage.length; j++)\n                                fromPage[j].textContent = vars['sitepage'];\n                            var toPage = document.getElementsByClassName('topage');\n                            for(var j = 0; j&lt;toPage.length; j++)\n                                toPage[j].textContent = vars['sitepages'];\n\n                            var index = vars['webpage'].split('.', 4)[3]\n                            var header = document.getElementById('minimal_layout_report_headers');\n                            if(header !== null){\n                                var companyHeader = header.children[index];\n                                header.textContent = '';\n                                header.appendChild(companyHeader);\n                            }\n                            var footer = document.getElementById('minimal_layout_report_footers');\n                            if(footer !== null){\n                                var companyFooter = footer.children[index];\n                                footer.textContent = '';\n                                footer.appendChild(companyFooter);\n                            }\n                        }\n                    </script>\n                </t>\n            </head>\n            <body class="container" onload="subst()">\n                <t t-raw="body"/>\n            </body>\n        </html>\n    </t>\n\n    	web/views/report_templates.xml	\N	\N	2020-03-20 13:31:42.692413	2020-03-20 13:31:42.692413	primary	t	1	1
