205	Editor layout	\N	web_editor.layout	16	qweb	<?xml version="1.0"?>\n<t name="Editor layout" t-name="web_editor.layout">&lt;!DOCTYPE html&gt;\n    <html t-att-lang="lang and lang.replace('_', '-')" t-att-data-editable="'1' if editable else None" t-att-data-translatable="'1' if translatable else None" t-att-data-edit_translations="'1' if edit_translations else None" t-att-data-main-object="repr(main_object) if editable else None">\n        <head>\n            <meta charset="utf-8"/>\n            <title>Odoo Editor layout</title>\n            <meta name="viewport" content="initial-scale=1"/>\n            <script type="text/javascript">\n                var callback = window.location.href.match(/callback=([^&amp;=]+)/)[1];\n\n                var odoo = {\n                    session_info: {\n                        is_superuser: <t t-esc="json.dumps(request.env.user._is_superuser())"/>,\n                        is_frontend: true, // this is not really the frontend here but this key is used to detect if xml has to be manually loaded\n                    },\n                    _modules: ['web_editor'],\n                    snippetsURL: '<t t-esc="snippets or ''"/>',\n                };\n            </script>\n            <t t-if="not dont_load_assets">\n                <t t-call-assets="web.assets_common" t-js="false"/>\n                <t t-call-assets="web.assets_frontend" t-js="false"/>\n                <t t-call-assets="web_editor.summernote" t-js="false"/>\n                <t t-call-assets="web_editor.assets_editor" t-js="false"/>\n\n                <t t-call-assets="web.assets_common" t-css="false"/>\n                <t t-call-assets="web_editor.summernote" t-css="false"/>\n                <t t-call-assets="web_editor.assets_editor" t-css="false"/>\n\n                <script type="text/javascript" src="/web/static/src/js/services/session.js"/>\n                <script type="text/javascript" src="/web_editor/static/src/js/content/body_manager.js"/>\n                <script type="text/javascript" src="/web_editor/static/src/js/root_widget.js"/>\n                <script type="text/javascript" src="/web_editor/static/src/js/iframe.js"/>\n                <script t-if="enable_editor and inline_mode" type="text/javascript" src="/web_editor/static/src/js/inline.js"/>\n            </t>\n            <script>\n                if (window.top.odoo &amp;&amp; !window.top.odoo[callback+"_updown"]) {\n                    window.top.odoo[callback+"_updown"] = function (value, fields_values) {\n                        var editable = document.getElementsByClassName("o_editable")[0];\n                        if (editable &amp;&amp; value !== editable.innerHTML) {\n                            editable.innerHTML = value;\n                        }\n                    };\n                }\n                if(window.odoo.define) {\n                    odoo.define('web.csrf', function (require) {\n                        var token = "<t t-esc="request.csrf_token(None)"/>";\n                        var core = require('web.core');\n                        core.csrf_token = token;\n                        core.qweb.default_dict.csrf_token = token;\n                    });\n                }\n            </script>\n            <t t-raw="head or ''"/>\n        </head>\n        <body id="web_editor_inside_iframe" onload="var fn=window.top.odoo &amp;&amp; window.top.odoo[callback+'_content']; if(fn) {fn();} else {console.warn('Please don\\'t open iframe without the odoo backend');}">\n            <div id="wrapwrap">\n                <main>\n                    <t t-raw="0"/>\n                </main>\n            </div>\n            <t t-raw="add_html or ''"/>\n        </body>\n    </html>\n</t>\n\n	web_editor/views/iframe.xml	\N	\N	2020-03-20 13:31:45.155974	2020-03-20 13:31:45.155974	primary	t	1	1
