357	report_pricelist	\N	product.report_pricelist	16	qweb	<?xml version="1.0"?>\n<t t-name="product.report_pricelist">\n    <t t-call="web.html_container">\n        <t t-call="web.internal_layout">\n            <div class="page">\n                <h2>Price List</h2>\n\n                <div class="row mt32 mb32">\n                    <div class="col-xs-3">\n                        <strong>Price List Name</strong>:<br/>\n                        <span t-esc="data['pricelist'].name"/>\n                    </div>\n                    <div class="col-xs-3">\n                        <strong>Currency</strong>:<br/>\n                        <span t-esc="data['pricelist'].currency_id.name"/>\n                    </div>\n                    <div class="col-xs-3">\n                        <strong>Print date</strong>:<br/>\n                        <t t-esc="datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')"/>\n                    </div>\n                </div>\n\n                <table class="table table-condensed">\n                    <thead>\n                        <tr>\n                            <th>\n                                <strong>Description</strong>\n                            </th>\n                            <t t-foreach="data['quantities']" t-as="quantity">\n                                <th><strong t-esc="'%s units' % quantity"/></th>\n                            </t>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <t t-foreach="data['categories_data']" t-as="categ_data">\n                            <tr>\n                                <td colspan="100">\n                                    <strong t-esc="categ_data['category'].name"/>\n                                </td>\n                            </tr>\n                            <tr t-foreach="categ_data['products']" t-as="product">\n                                <td>\n                                    <t t-if="product.code">\n                                        [<span t-esc="product.code"/>]\n                                    </t> \n                                    <span t-esc="product.name"/>\n                                    <span t-foreach="product.attribute_value_ids" t-as="attribute_value">\n                                        <span t-if="attribute_value_first">-</span>\n                                        <span t-if="not attribute_value_last" t-esc="attribute_value.name+','"/>\n                                        <span t-else="" t-esc="attribute_value.name"/>\n                                    </span>\n                                </td>\n                                <t t-foreach="data['quantities']" t-as="quantity">\n                                    <td><strong t-esc="categ_data['prices'][product.id][quantity]" t-options="{                                                     'widget': 'float',                                                     'decimal_precision': 'Product Price'}"/>\n                                    </td>\n                                </t>\n                            </tr>\n                        </t>\n                    </tbody>\n                </table>\n            </div>\n        </t>\n    </t>\n</t>\n	product/report/product_pricelist_templates.xml	\N	\N	2020-03-20 13:32:32.335117	2020-03-20 13:32:32.335117	primary	t	1	1
