487	report_invoice_document	\N	account.report_invoice_document	16	qweb	<?xml version="1.0"?>\n<t t-name="account.report_invoice_document">\n            <t t-call="web.external_layout">\n                <t t-set="o" t-value="o.with_context(lang=o.partner_id.lang)"/>\n                <div class="page">\n                    <div class="row">\n                        <div name="invoice_address" class="col-xs-5 col-xs-offset-7">\n                            <address t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                            <div t-if="o.partner_id.vat" class="mt16"><t t-esc="o.company_id.country_id.vat_label or 'TIN'"/>: <span t-field="o.partner_id.vat"/></div>\n                        </div>\n                    </div>\n\n                    <h2>\n                        <span t-if="o.type == 'out_invoice' and (o.state == 'open' or o.state == 'paid')">Invoice</span>\n                        <span t-if="o.type == 'out_invoice' and o.state == 'draft'">Draft Invoice</span>\n                        <span t-if="o.type == 'out_invoice' and o.state == 'cancel'">Cancelled Invoice</span>\n                        <span t-if="o.type == 'out_refund'">Credit Note</span>\n                        <span t-if="o.type == 'in_refund'">Vendor Credit Note</span>\n                        <span t-if="o.type == 'in_invoice'">Vendor Bill</span>\n                        <span t-field="o.number"/>\n                    </h2>\n\n                    <div class="row mt32 mb32">\n                        <div class="col-xs-2" t-if="o.name">\n                            <strong>Description:</strong>\n                            <p t-field="o.name"/>\n                        </div>\n                        <div class="col-xs-2" t-if="o.date_invoice">\n                            <strong>Invoice Date:</strong>\n                            <p t-field="o.date_invoice"/>\n                        </div>\n                        <div class="col-xs-2" t-if="o.date_due and o.type == 'out_invoice' and (o.state == 'open' or o.state == 'paid')">\n                            <strong>Due Date:</strong>\n                            <p t-field="o.date_due"/>\n                        </div>\n                        <div class="col-xs-2" t-if="o.origin">\n                            <strong>Source:</strong>\n                            <p t-field="o.origin"/>\n                        </div>\n                        <div class="col-xs-2" t-if="o.partner_id.ref">\n                            <strong>Customer Code:</strong>\n                            <p t-field="o.partner_id.ref"/>\n                        </div>\n                        <div name="reference" class="col-xs-2" t-if="o.reference">\n                            <strong>Reference:</strong>\n                            <p t-field="o.reference"/>\n                        </div>\n                    </div>\n\n                    <!-- Is there a discount on at least one line? -->\n                    <t t-set="display_discount" t-value="any([l.discount for l in o.invoice_line_ids])"/>\n\n                    <table class="table table-condensed" name="invoice_line_table">\n                        <thead>\n                            <tr>\n                                <th>Description</th>\n                                <th class="hidden">Source Document</th>\n                                <th class="text-right">Quantity</th>\n                                <th class="text-right">Unit Price</th>\n                                <th t-if="display_discount" class="text-right">Disc.(%)</th>\n                                <th class="text-right">Taxes</th>\n                                <th class="text-right">Amount</th>\n                            </tr>\n                        </thead>\n                        <tbody class="invoice_tbody">\n                            <tr t-foreach="o.invoice_line_ids" t-as="l">\n                                <td><span t-field="l.name"/></td>\n                                <td class="hidden"><span t-field="l.origin"/></td>\n                                <td class="text-right">\n                                    <span t-field="l.quantity"/>\n                                    <span t-field="l.uom_id" groups="product.group_uom"/>\n                                </td>\n                                <td class="text-right">\n                                    <span t-field="l.price_unit"/>\n                                </td>\n                                <td t-if="display_discount" class="text-right">\n                                    <span t-field="l.discount"/>\n                                </td>\n                                <td class="text-right">\n                                    <span t-esc="', '.join(map(lambda x: (x.description or x.name), l.invoice_line_tax_ids))"/>\n                                </td>\n                                <td class="text-right" id="subtotal">\n                                    <span t-field="l.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                </td>\n                            </tr>\n                            <tr t-foreach="range(max(5-len(o.invoice_line_ids),0))" t-as="l">\n                                <td t-translation="off">&amp;nbsp;</td>\n                                <td class="hidden"/>\n                                <td/>\n                                <td/>\n                                <td t-if="display_discount"/>\n                                <td/>\n                                <td/>\n                            </tr>\n                        </tbody>\n                    </table>\n\n                    <div class="clearfix">\n                        <div id="total" class="row">\n                            <div class="col-xs-4 pull-right">\n                                <table class="table table-condensed" style="min-width: 250px;max-width: 400px;page-break-inside: avoid;">\n                                    <tr class="border-black" style="border-bottom:1px solid #dddddd;">\n                                        <td><strong>Subtotal</strong></td>\n                                        <td class="text-right">\n                                            <span t-field="o.amount_untaxed" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                        </td>\n                                    </tr>\n                                    <t t-foreach="o._get_tax_amount_by_group()" t-as="amount_by_group">\n                                        <tr style="border-bottom:1px solid #dddddd;">\n                                            <t t-if="len(o.tax_line_ids) == 1 and o.amount_untaxed == amount_by_group[2]">\n                                                <td><span t-esc="amount_by_group[0]"/></td>\n                                                <td class="text-right">\n                                                    <span t-esc="amount_by_group[3]"/>\n                                                </td>\n                                            </t>\n                                            <t t-else="">\n                                                <td>\n                                                    <span t-esc="amount_by_group[0]"/>\n                                                    <span>&amp;nbsp;<span>on</span>\n                                                        <t t-esc="amount_by_group[4]"/>\n                                                    </span>\n                                                </td>\n                                                <td class="text-right">\n                                                    <span t-esc="amount_by_group[3]"/>\n                                                </td>\n                                            </t>\n                                        </tr>\n                                    </t>\n                                    <tr class="border-black">\n                                        <td><strong>Total</strong></td>\n                                        <td class="text-right">\n                                            <span t-field="o.amount_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </div>\n                        </div>\n                    </div>\n                    <p t-if="o.comment">\n                        <span t-field="o.comment"/>\n                    </p>\n                    <p t-if="o.payment_term_id">\n                        <span t-field="o.payment_term_id.note"/>\n                    </p>\n                    <p t-if="o.fiscal_position_id.note">\n                        <span t-field="o.fiscal_position_id.note"/>\n                    </p>\n                </div>\n            </t>\n        </t>\n\n        	account/views/report_invoice.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
