493	account.invoice.report.search	account.invoice.report	\N	16	search	<?xml version="1.0"?>\n<search string="Invoices Analysis">\n                <filter string="My Invoices" name="my_invoice" domain="[('user_id', '=', uid)]"/>\n                <separator/>\n                <field name="date"/>\n                <filter string="This Year" name="thisyear" domain="['|', ('date', '=', False), '&amp;',('date','&lt;=', time.strftime('%Y-12-31')),('date','&gt;=',time.strftime('%Y-01-01'))]" help="Journal invoices with period in current year"/>\n                <separator/>\n                <filter string="To Invoice" domain="[('state','=','draft')]" help="Draft Invoices"/>\n                <filter string="Invoiced" name="current" domain="[('state','not in', ('draft','cancel'))]"/>\n                <separator/>\n                <filter string="This Month" name="this_month" domain="[('date', '&gt;=', context_today().strftime('%Y-%m-01'))]"/>\n                <filter string="Last Month" name="last_month" domain="['&amp;', ('date', '&gt;=', (context_today() - relativedelta(months=1)).strftime('%Y-%m-01')), ('date', '&lt;', context_today().strftime('%Y-%m-01'))]"/>\n                <separator/>\n                <filter string="Customer" name="customer" domain="['|', ('type','=','out_invoice'),('type','=','out_refund')]"/>\n                <filter string="Vendor" name="supplier" domain="['|', ('type','=','in_invoice'),('type','=','in_refund')]"/>\n                <separator/>\n                <filter string="Invoice" domain="['|', ('type','=','out_invoice'),('type','=','in_invoice')]"/>\n                <filter string="Credit Note" domain="['|', ('type','=','out_refund'),('type','=','in_refund')]"/>\n                <field name="partner_id" operator="child_of"/>\n                <field name="user_id"/>\n                <field name="categ_id" filter_domain="[('categ_id', 'child_of', self)]"/>\n                <field name="account_analytic_id"/>\n                <group expand="1" string="Group By">\n                    <filter string="Partner" name="partner_id" context="{'group_by':'partner_id','residual_visible':True}"/>\n                    <filter string="Salesperson" name="user" context="{'group_by':'user_id'}"/>\n                    <filter string="Product Category" name="category_product" context="{'group_by':'categ_id','residual_invisible':True}"/>\n                    <filter string="Status" context="{'group_by':'state'}"/>\n                    <filter string="Company" context="{'group_by':'company_id'}" groups="base.group_multi_company"/>\n                    <separator orientation="vertical"/>\n                    <filter string="Date" context="{'group_by':'date'}"/>\n                    <filter string="Due Month" context="{'group_by':'date_due:month'}"/>\n                    <filter string="Analytic Account" name="account_analytic_id" context="{'group_by':'account_analytic_id'}" groups="analytic.group_analytic_accounting"/>\n                </group>\n            </search>\n        	account/report/account_invoice_report_view.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
494	account.report_overdue_document	\N	account.report_overdue_document	16	qweb	<?xml version="1.0"?>\n<t t-name="account.report_overdue_document">\n    <t t-call="web.external_layout">\n        <div class="page">\n            <div class="row">\n                <div class="col-xs-5 col-xs-offset-7">\n                    <!-- When partner is a company, its name is included in contact_address -->\n                    <span t-if="not o.is_company"><span t-field="o.name"/><br/></span>\n                    <span t-raw="o.contact_address.replace('\\n\\n', '\\n').replace('\\n', '&lt;br&gt;')"/>\n                    <span t-field="o.vat"/>\n                </div>\n                <p>\n                    Document: Customer account statement<br/>\n                    Date: <span t-esc="Date"/><br/>\n                    <t t-if="o.ref">Customer ref: <span t-field="o.ref"/></t>\n                </p>\n\n                <t t-if="Lines[o.id]">\n                    <span t-field="res_company.with_context(lang=o.lang).overdue_msg"/>\n                    <table class="table table-condensed" t-foreach="Lines[o.id]" t-as="currency">\n                        <thead>\n                            <tr>\n                                <th>Reference number</th>\n                                <th class="text-center">Date</th>\n                                <th class="text-center">Due Date</th>\n                                <th>Communication</th>\n                                <th class="text-right">Due</th>\n                                <th class="text-right">Paid</th>\n                                <th class="text-center">Litigation</th>\n                            </tr>\n                        </thead>\n                        <tr t-foreach="Lines[o.id][currency]" t-as="line">\n                            <td>\n                                <span t-esc="line['move_id']"/>\n                            </td>\n                            <td>\n                                <span t-esc="line['date']"/>\n                            </td>\n                            <td>\n                                <span t-esc="line['date_maturity']"/>\n                            </td>\n                            <td>\n                                <t t-if="line['name'] != '/'"><span t-esc="line['name']"/></t>\n                                <span t-esc="line['ref']"/>\n                            </td>\n                            <td class="text-right">\n                                <span t-esc="line['debit']" t-options="{'widget': 'monetary', 'display_currency': currency}"/>\n                            </td>\n                            <td class="text-right">\n                                <span t-esc="line['credit']" t-options="{'widget': 'monetary', 'display_currency': currency}"/>\n                            </td>\n                            <td class="text-center">\n                                <span t-if="line['blocked']">x</span>\n                            </td>\n                        </tr>\n                        <tr>\n                            <td colspan="3"/>\n                            <td><strong>Subtotal :</strong></td>\n                            <td class="text-right"><span t-esc="Totals[o.id][currency]['due']" t-options="{'widget': 'monetary', 'display_currency': currency}"/></td>\n                            <td class="text-right"><span t-esc="Totals[o.id][currency]['paid']" t-options="{'widget': 'monetary', 'display_currency': currency}"/></td>\n                            <td class="text-right"><span t-esc="Totals[o.id][currency]['mat']" t-options="{'widget': 'monetary', 'display_currency': currency}"/></td>\n                            <td/>\n                        </tr>\n                        <tr>\n                            <td colspan="3"/>\n                            <td><strong>Balance :</strong></td>\n                            <td class="text-right">\n                                <span t-esc="Totals[o.id][currency]['due'] - Totals[o.id][currency]['paid']" t-options="{'widget': 'monetary', 'display_currency': currency}"/>\n                            </td>\n                        </tr>\n                    </table>\n                </t>\n                <p t-if="not Lines[o.id]">\n                    <strong>There is nothing due with this customer.</strong>\n                </p>\n            </div>\n        </div>\n   </t>\n</t>\n\n	account/views/report_overdue.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
