542	payment.acquirer.form	payment.acquirer	\N	16	form	<?xml version="1.0"?>\n<form string="Payment Acquirer">\n                    <field name="environment" invisible="1"/>\n                    <field name="fees_implemented" invisible="1"/>\n                    <field name="token_implemented" invisible="1"/>\n                    <field name="authorize_implemented" invisible="1"/>\n                    <sheet>\n                        <field name="module_id" invisible="1"/>\n                        <field name="module_state" invisible="1"/>\n                        <div class="oe_button_box" name="button_box" attrs="{'invisible': ['&amp;', ('module_id', '!=', False), ('module_state', '!=', 'installed')]}">\n                            <!-- transfer referenced here due to view inheritance issue in current master (post-saas-16) -->\n                            <button name="toggle_environment_value" attrs="{'invisible': ['|', ('environment', '=', 'test'), ('provider', '=', 'transfer')]}" class="oe_stat_button" type="object" icon="fa-play">\n                                <div class="o_stat_info o_field_widget">\n                                    <span class="text-success">Production</span>\n                                    <span class="o_stat_text">Environment</span>\n                                </div>\n                            </button>\n                            <!-- transfer referenced here due to view inheritance issue in current master (post-saas-16) -->\n                            <button name="toggle_environment_value" attrs="{'invisible': ['|', ('environment', '=', 'prod'), ('provider', '=', 'transfer')]}" class="oe_stat_button" type="object" icon="fa-stop">\n                                <div class="o_stat_info o_field_widget">\n                                    <span class="o_warning_text">Test</span>\n                                    <span class="o_stat_text">Environment</span>\n                                </div>\n                            </button>\n                            <button name="toggle_website_published" class="oe_stat_button" type="object" icon="fa-globe">\n                                <field name="website_published" widget="boolean_button" options="{&quot;terminology&quot;: {&quot;string_true&quot;: &quot;Published&quot;, &quot;hover_false&quot;: &quot;Publish&quot;}}"/>\n                            </button>\n                        </div>\n                        <field name="image" widget="image" class="oe_avatar" options="{&quot;preview_image&quot;: &quot;image_medium&quot;}"/>\n                        <div class="oe_title">\n                            <h1><field name="name" placeholder="Name"/></h1>\n                        </div>\n                        <div attrs="{'invisible': ['|', ('module_state', '=', 'installed'), ('module_id', '=', False)]}">\n                            <button type="object" class="btn btn-primary" name="button_immediate_install" string="Install"/>\n                            <div class="o_payment_acquirer_desc">\n                                <field name="description"/>\n                            </div>\n                        </div>\n                        <group name="acquirer_base" col="2" attrs="{'invisible': ['&amp;', ('module_id', '!=', False), ('module_state', '!=', 'installed')]}">\n                            <group name="acquirer_left">\n                                <field name="provider" groups="base.group_no_one"/>\n                                <field name="company_id" groups="base.group_multi_company" options="{&quot;no_open&quot;:True}"/>\n                            </group>\n                        </group>\n                        <notebook attrs="{'invisible': ['&amp;', ('module_id', '!=', False), ('module_state', '!=', 'installed')]}">\n                            <page string="Credentials" name="acquirer_credentials">\n                                <group name="acquirer">\n                                <