509	report_financial	\N	account.report_financial	16	qweb	<?xml version="1.0"?>\n<t t-name="account.report_financial">\n    <t t-call="web.html_container">\n        <t t-foreach="docs" t-as="o">\n            <t t-call="web.internal_layout">\n                <div class="page">\n                    <h2 t-esc="data['account_report_id'][1]"/>\n\n                    <div class="row mt32 mb32">\n                        <div class="col-xs-4">\n                            <strong>Target Moves:</strong>\n                            <p>\n                                <span t-if="data['target_move'] == 'all'">All Entries</span>\n                                <span t-if="data['target_move'] == 'posted'">All Posted Entries</span>\n                            </p>\n                        </div>\n                        <div class="col-xs-4">\n                            <p>\n                                <t t-if="data['date_from']"><strong>Date from :</strong> <span t-esc="data['date_from']"/><br/></t>\n                                <t t-if="data['date_to']"><strong>Date to :</strong> <span t-esc="data['date_to']"/></t>\n                            </p>\n                        </div>\n                    </div>\n\n                    <table class="table table-condensed" t-if="data['debit_credit'] == 1">\n                        <thead>\n                            <tr>\n                                <th>Name</th>\n                                <th class="text-right">Debit</th>\n                                <th class="text-right">Credit</th>\n                                <th class="text-right">Balance</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr t-foreach="get_account_lines" t-as="a">\n                                <t t-if="a['level'] != 0">\n                                    <t t-if="a.get('level') &gt; 3"><t t-set="style" t-value="'font-weight: normal;'"/></t>\n                                    <t t-if="not a.get('level') &gt; 3"><t t-set="style" t-value="'font-weight: bold;'"/></t>\n\n                                    <td>\n                                        <span style="color: white;" t-esc="'..' * a.get('level', 0)"/>\n                                        <span t-att-style="style" t-esc="a.get('name')"/>\n                                    </td>\n                                    <td class="text-right" style="white-space: text-nowrap;">\n                                        <span t-att-style="style" t-esc="a.get('debit')" t-options="{'widget': 'monetary', 'display_currency': res_company.currency_id}"/>\n                                    </td>\n                                    <td class="text-right" style="white-space: text-nowrap;">\n                                        <span t-att-style="style" t-esc="a.get('credit')" t-options="{'widget': 'monetary', 'display_currency': res_company.currency_id}"/>\n                                    </td>\n                                    <td class="text-right" style="white-space: text-nowrap;">\n                                        <span t-att-style="style" t-esc="a.get('balance')" t-options="{'widget': 'monetary', 'display_currency': res_company.currency_id}"/>\n                                    </td>\n                                </t>\n                            </tr>\n                        </tbody>\n                    </table>\n\n                    <table class="table table-condensed" t-if="not data['enable_filter'] and not data['debit_credit']">\n                        <thead>\n                            <tr>\n                                <th>Name</th>\n                                <th class="text-right">Balance</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr t-foreach="get_account_lines" t-as="a">\n                                <t t-if="a['level'] != 0">\n                                    <t t-if="a.get('level') &gt; 3"><t t-set="style" t-value="'font-weight: normal;'"/></t>\n                                    <t t-if="not a.get('level') &gt; 3"><t t-set="style" t-value="'font-weight: bold;'"/></t>\n\n                                    <td>\n                                        <span style="color: white;" t-esc="'..' * a.get('level', 0)"/>\n                                        <span t-att-style="style" t-esc="a.get('name')"/>\n                                    </td>\n                                    <td class="text-right"><span t-att-style="style" t-esc="a.get('balance')" t-options="{'widget': 'monetary', 'display_currency': res_company.currency_id}"/></td>\n                                </t>\n                            </tr>\n                        </tbody>\n                    </table>\n\n                    <table class="table table-condensed" t-if="data['enable_filter'] == 1 and not data['debit_credit']">\n                        <thead>\n                            <tr>\n                                <th>Name</th>\n                                <th class="text-right">Balance</th>\n                                <th class="text-right"><span t-esc="data['label_filter']"/></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr t-foreach="get_account_lines" t-as="a">\n                                <t t-if="a['level'] != 0">\n                                    <t t-if="a.get('level') &gt; 3"><t t-set="style" t-value="'font-weight: normal;'"/></t>\n                                    <t t-if="not a.get('level') &gt; 3"><t t-set="style" t-value="'font-weight: bold;'"/></t>\n                                    <td>\n                                        <span style="color: white;" t-esc="'..'"/>\n                                        <span t-att-style="style" t-esc="a.get('name')"/>\n                                    </td>\n                                    <td class="text-right"><span t-att-style="style" t-esc="a.get('balance')" t-options="{'widget': 'monetary', 'display_currency': res_company.currency_id}"/></td>\n                                    <td class="text-right"><span t-att-style="style" t-esc="a.get('balance_cmp')"/></td>\n                                </t>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </t>\n        </t>\n    </t>\n</t>\n	account/views/report_financial.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
510	Aged Partner Balance	account.aged.trial.balance	\N	16	form	<?xml version="1.0"?>\n<form string="Report Options">\n                <separator string="Aged Partner Balance"/>\n                <label string="Aged Partner Balance is a more detailed report of your receivables by intervals. Odoo calculates a table of credit balance by start Date. So if you request an interval of 30 days Odoo generates an analysis of creditors for the past month, past two months, and so on. "/>\n                <group col="4">\n                    <field name="date_from"/>\n                    <field name="period_length"/>\n                    <newline/>\n                    <field name="result_selection" widget="radio"/>\n                    <field name="target_move" widget="radio"/>\n                </group>\n                <field name="journal_ids" required="0" invisible="1"/>\n                <footer>\n                    <button name="check_report" string="Print" type="object" default_focus="1" class="oe_highlight"/>\n                    <button string="Cancel" class="btn btn-default" special="cancel"/>\n                </footer>\n            </form>\n        	account/wizard/account_report_aged_partner_balance_view.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
