513	res.config.settings.view.form.inherit.account	res.config.settings	\N	40	form	<?xml version="1.0"?>\n<xpath expr="//div[hasclass('settings')]" position="inside">\n                    <div class="app_settings_block o_not_app" data-string="Invoicing" string="Invoicing" data-key="account_invoicing" groups="account.group_account_manager">\n                        <field name="has_chart_of_accounts" invisible="1"/>\n                        <field name="has_accounting_entries" invisible="1"/>\n                            <h2 attrs="{'invisible': [('has_accounting_entries','!=',False)]}">Fiscal Localization</h2>\n                            <div class="row mt16 o_settings_container">\n                                <div class="col-xs-12 col-md-6 o_setting_box" attrs="{'invisible': [('has_accounting_entries','!=',False)]}">\n                                    <div class="o_setting_left_pane"/>\n                                    <div class="o_setting_right_pane">\n                                        <label string="Fiscal Localization"/>\n                                        <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." groups="base.group_multi_company"/>\n                                        <div class="text-muted">\n                                            Taxes, fiscal positions, chart of accounts &amp; legal statements for your country\n                                        </div>\n                                        <div class="content-group">\n                                            <div class="row mt16">\n                                                <label string="Package" class="col-md-3 o_light_label"/>\n                                                <field name="chart_template_id" widget="selection"/>\n                                            </div>\n                                            <div>\n                                                <button name="223" icon="fa-arrow-right" type="action" string="Install More Packages" class="btn-link"/>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        <t groups="account.group_account_user">\n                            <h2>Setup</h2>\n                            <div class="row mt16 o_settings_container">\n                                <div class="col-xs-12 col-md-6 o_setting_box">\n                                    <div class="o_setting_left_pane">\n                                        <field name="account_hide_setup_bar" widget="upgrade_boolean"/>\n                                    </div>\n                                    <div class="o_setting_right_pane">\n                                        <label string="Hide Setup Bar"/>\n                                        <div class="text-muted">\n                                            Deactivate setup bar on the dashboard\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                        <h2>Taxes</h2>\n                        <div class="row mt16 o_settings_container">\n                            <div class="col-xs-12 col-md-6 o_setting_box" title="These taxes are set in any new product created.">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <label string="Default Taxes"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." groups="base.group_multi_company"/>\n                                    <div class="text-muted">\n                                        Default taxes applied to local transactions\n                                    </div>\n                                    <div class="content-group">\n                                        <div class="row mt16">\n                                            <label string="Sales Tax" for="default_sale_tax_id" class="col-md-3 o_light_label"/>\n                                            <field name="default_sale_tax_id" domain="[('type_tax_use', 'in', ('sale', 'all')), ('company_id', '=', company_id)]"/>\n                                        </div>\n                                        <div class="row">\n                                            <label string="Purchase Tax" for="default_purchase_tax_id" class="col-md-3 o_light_label"/>\n                                            <field name="default_purchase_tax_id" domain="[('type_tax_use', 'in', ('purchase', 'all')), ('company_id', '=', company_id)]"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="rounding_method" title="A rounding per line is advised if your prices are tax-included. That way, the sum of line subtotals equals the total with taxes.">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <label string="Rounding Method"/>\n                                    <div class="text-muted">\n                                        How total tax amount is computed in orders and invoices\n                                    </div>\n                                     <div class="content-group">\n                                        <field name="tax_calculation_rounding_method" class="o_light_label mt16" widget="radio"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="taxcloud_settings">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_taxcloud"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="account_taxcloud_right_pane">\n                                    <label for="module_account_taxcloud" string="TaxCloud"/>\n                                    <div class="text-muted">\n                                        Compute tax rates based on U.S. ZIP codes\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="eu_service" title="If you're selling digital goods to customers in the EU, you must charge VAT based on your customers' locations. This rule applies regardless of you are located. Digital goods are defined in the legislation as broadcasting, telecommunications, and services that are electronically supplied instead of shipped. Gift cards sent online are not included in the definition.">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_l10n_eu_service"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="l10n_eu_service_right_pane">\n                                    <label for="module_l10n_eu_service"/>\n                                    <div class="text-muted">\n                                        Apply right VAT rates for digital products sold in EU\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" title="Select this if the taxes should use cash basis, which will create an entry for such taxes on a given account during reconciliation." groups="account.group_account_user">\n                                <div class="o_setting_left_pane">\n                                    <field name="tax_exigibility"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="tax_exigibility"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." groups="base.group_multi_company"/>\n                                    <div class="text-muted">\n                                        Allow to configure taxes using cash basis\n                                    </div>\n                                    <div class="content-group" attrs="{'invisible': [('tax_exigibility', '=', False)]}">\n                                        <div class="row mt16">\n                                            <label for="tax_cash_basis_journal_id" class="col-md-3 o_light_label"/>\n                                            <field name="tax_cash_basis_journal_id"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Currencies</h2>\n                        <div class="row mt16 o_settings_container">\n                            <div class="col-xs-12 col-md-6 o_setting_box">\n                                <div class="o_setting_left_pane"/>\n                                <div class="o_setting_right_pane">\n                                    <label string="Main Currency"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." groups="base.group_multi_company"/>\n                                    <div class="text-muted">\n                                        Main currency of your company\n                                    </div>\n                                    <div class="content-group">\n                                        <div class="row mt16">\n                                            <label for="currency_id" class="col-md-3 o_light_label"/>\n                                            <field name="currency_id" options="{'no_create_edit': True, 'no_open': True}"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_multi_currency"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label string="Multi-Currencies" for="group_multi_currency"/>\n                                    <div class="text-muted">\n                                        Record transactions in foreign currencies\n                                    </div>\n                                    <div class="content-group" attrs="{'invisible': [('group_multi_currency', '=', False)]}">\n                                        <div class="mt16">\n                                            <button name="62" icon="fa-arrow-right" type="action" string="Activate Other Currencies" class="btn-link"/>\n                                        </div>\n                                        <div class="row mt16">\n                                            <label for="currency_exchange_journal_id" class="col-md-3 o_light_label"/>\n                                            <field name="currency_exchange_journal_id"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" attrs="{'invisible': [('group_multi_currency', '=', False)]}">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_currency_rate_live" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_currency_rate_live"/>\n                                    <div class="text-muted" id="update_currency_live">\n                                        Update exchange rates automatically\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Customer Payments</h2>\n                        <div class="row mt16 o_settings_container">\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="account_followup" title="This feature is useful if you issue a high amounts of invoices.">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_reports_followup" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_account_reports_followup"/>\n                                    <div class="text-muted">\n                                        Use follow-up levels and schedule actions\n                                    </div>\n                                    <div id="account_reports_followup" class="content-group" attrs="{'invisible': [('module_account_reports_followup', '=', False)]}">\n                                        <div class="text-warning mt16 mb4">\n                                            Save this page and come back here to set up the feature.\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_payment"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label string="Online Payment"/>\n                                    <div class="text-muted">\n                                        Let your customers pay their invoices online\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" groups="account.group_account_user">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_batch_deposit" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label string="Batch Deposits"/>\n                                    <div class="text-muted">\n                                        Group received checks before depositing them to the bank\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" title="If you check this box, you will be able to collect payments using SEPA Direct Debit mandates.">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_sepa_direct_debit" class="oe_inline" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="sepa_direct_debit_right_pane">\n                                    <label string="SEPA Direct Debit (SDD)" for="module_account_sepa"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." groups="base.group_multi_company"/>\n                                    <div class="text-muted">\n                                        Collect customer payments in one-click using Euro SEPA Service.\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <h2>Supplier Payments</h2>\n                        <div class="row mt16 o_settings_container">\n                            <div class="col-xs-12 col-md-6 o_setting_box" groups="account.group_account_user">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_l10n_us_check_printing" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label string="Checks" for="module_l10n_us_check_printing"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." groups="base.group_multi_company"/>\n                                    <div class="text-muted" id="print_bills_payment">\n                                        Print checks to pay your vendors\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" title="If you check this box, you will be able to register your payment using SEPA.">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_sepa" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane" name="sepa_right_pane">\n                                    <label for="module_account_sepa"/>\n                                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific." groups="base.group_multi_company"/>\n                                    <div class="text-muted">\n                                        Pay your bills in one-click using Euro SEPA service\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <t groups="account.group_account_user">\n                            <h2>Fiscal Periods</h2>\n                            <div class="row mt16 o_settings_container" id="accounting_reports">\n                                <div class="col-xs-12 col-md-6 o_setting_box" id="fiscalyear" invisible="1"/>\n                                <div class="col-xs-12 col-md-6 o_setting_box" id="dynamic_report" invisible="1" groups="account.group_account_user">\n                                    <div class="o_setting_left_pane">\n                                        <field name="module_account_reports" widget="upgrade_boolean"/>\n                                    </div>\n                                    <div class="o_setting_right_pane">\n                                        <label for="module_account_reports"/>\n                                        <div class="text-muted" id="account_reports">\n                                            Navigate easily through reports and see what is behind the numbers\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <h2>Bank &amp; Cash</h2>\n                            <div class="row mt16 o_settings_container" id="bank_cash">\n                                <div class="col-xs-12 col-md-6 o_setting_box" id="account_yodlee" title="Get your bank statements automatically imported every 4 hours, or in one-click, using Yodlee and Plaid services. Once installed, set “Bank Feeds” to “Bank Synchronization” in bank account settings. Then, click “Configure” on the online account to enter your bank credentials.">\n                                    <div class="o_setting_left_pane">\n                                        <field name="module_account_yodlee" widget="upgrade_boolean"/>\n                                    </div>\n                                    <div class="o_setting_right_pane">\n                                        <label string="Automatic Import"/>\n                                        <div class="text-muted">\n                                            Import your bank statements automatically\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class="col-xs-12 col-md-6 o_setting_box" title="Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.">\n                                    <div class="o_setting_left_pane">\n                                        <field name="module_account_bank_statement_import_csv" widget="upgrade_boolean"/>\n                                    </div>\n                                    <div class="o_setting_right_pane">\n                                        <label string="CSV Import"/>\n                                        <div class="text-muted">\n                                            Import your bank statements in CSV\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class="col-xs-12 col-md-6 o_setting_box" title="Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.">\n                                    <div class="o_setting_left_pane">\n                                        <field name="module_account_bank_statement_import_qif" widget="upgrade_boolean"/>\n                                    </div>\n                                    <div class="o_setting_right_pane">\n                                        <label string="QIF Import"/>\n                                        <div class="text-muted">\n                                            Import your bank statements in QIF\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class="col-xs-12 col-md-6 o_setting_box" title="Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.">\n                                    <div class="o_setting_left_pane">\n                                        <field name="module_account_bank_statement_import_ofx" widget="upgrade_boolean"/>\n                                    </div>\n                                    <div class="o_setting_right_pane">\n                                        <label string="OFX Import"/>\n                                        <div class="text-muted">\n                                            Import your bank statements in OFX\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class="col-xs-12 col-md-6 o_setting_box" title="Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.">\n                                    <div class="o_setting_left_pane">\n                                        <field name="module_account_bank_statement_import_camt" widget="upgrade_boolean"/>\n                                    </div>\n                                    <div class="o_setting_right_pane">\n                                        <label string="CAMT Import"/>\n                                        <div class="text-muted">\n                                            Import your bank statements in CAMT.053\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                        <h2>Analytics</h2>\n                        <div class="row mt16 o_settings_container" id="analytic">\n                            <div class="col-xs-12 col-md-6 o_setting_box" title="Allows you to use the analytic accounting." groups="account.group_account_user">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_analytic_accounting"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="group_analytic_accounting"/>\n                                    <div class="text-muted">\n                                        Track costs &amp; revenues by project, department, etc.\n                                    </div>\n                                    <div class="content-group" attrs="{'invisible': [('group_analytic_accounting', '=', False)]}">\n                                        <div class="mt16" id="analytic_account_link">\n                                            <button name="98" icon="fa-arrow-right" type="action" string="Analytic Accounts" class="btn-link"/>\n                                        </div>\n                                        <div>\n                                            <button name="96" icon="fa-arrow-right" type="action" string="Tags for Multidimensional Analytics" class="btn-link"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="account_budget" title="This allows accountants to manage analytic and crossovered budgets. Once the master budgets and the budgets are defined, the project managers can set the planned amount on each analytic account." groups="account.group_account_user">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_budget"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_account_budget"/>\n                                    <div class="text-muted">\n                                        Compare actual revenues &amp; costs with budgets\n                                    </div>\n                                    <div id="msg_account_budget" class="content-group" attrs="{'invisible': [('module_account_budget', '=', False)]}">\n                                        <div class="text-warning mt16 mb4">\n                                            Save this page and come back here to set up the feature.\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_product_margin"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label string="Margin Analysis"/>\n                                    <div class="text-muted">\n                                        Monitor your product margins from invoices\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2>Invoices</h2>\n                        <div class="row mt16 o_settings_container" id="invoicing_settings">\n                            <div class="col-xs-12 col-md-6 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_warning_account"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="group_warning_account"/>\n                                    <div class="text-muted">\n                                        Get warnings when invoicing specific customers\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_print_docsaway" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_print_docsaway"/>\n                                    <div class="text-muted">\n                                        Mail your invoices in one-click using <a target="_blank" href="https://www.docsaway.com/">Docsaway</a>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="group_cash_rounding"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="group_cash_rounding"/>\n                                    <div class="text-muted">\n                                        Define the smallest coinage of the currency used to pay by cash.\n                                    </div>\n                                    <div>\n                                        <button name="212" icon="fa-arrow-right" type="action" string="Cash Roundings" class="btn-link" attrs="{'invisible': [('group_cash_rounding', '=', False)]}"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <h2 groups="account.group_account_user">Automated Entries</h2>\n                        <div class="row mt16 o_settings_container" id="recommended_apps" groups="account.group_account_user">\n                            <div class="col-xs-12 col-md-6 o_setting_box" id="asset_types" title="This allows you to manage the assets owned by a company or a person. It keeps track of the depreciation occurred on those assets, and creates account move for those depreciation lines.">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_asset"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_account_asset"/>\n                                    <div class="text-muted">\n                                        Use depreciation boards, automate amortization entries\n                                    </div>\n                                    <div id="msg_account_asset" class="content-group" attrs="{'invisible': [('module_account_asset', '=', False)]}">\n                                        <div class="text-warning mt16 mb4">\n                                            Save this page and come back here to set up the feature.\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class="col-xs-12 col-md-6 o_setting_box" title="This allows you to manage the revenue recognition on selling products. It keeps track of the installments occurred on those revenue recognitions, and creates account moves for those installment lines.">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_deferred_revenue" widget="upgrade_boolean"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_account_deferred_revenue" string="Deferred Revenues Management"/>\n                                    <div class="text-muted">\n                                        Automate deferred revenues entries for multi-year contracts\n                                    </div>\n                                    <div id="msg_automate_deferred_revenues" class="content-group" attrs="{'invisible': [('module_account_deferred_revenue', '=', False)]}">\n                                        <div class="text-warning mt16 mb4">\n                                            Save this page and come back here to set up the feature.\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </xpath>\n            	account/views/res_config_settings_views.xml	153	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	extension	t	1	1
514	account_planner	\N	account.account_planner	16	qweb	<?xml version="1.0"?>\n<t t-name="account.account_planner">\n        <t t-call="web_planner.pages">\n            <t t-call="web_planner.page">\n                <t t-set="page_title">Welcome</t>\n                <t t-set="hide_mark_as_done" t-value="True"/>\n                <div class="o_planner_intro">\n                    <p>\n                        This guide will help you get started with Odoo Accounting.\n                        Once you're done, you'll benefit from:\n                    </p>\n                    <ul>\n                        <li><strong>Reduced data entry:</strong> no need to manually create invoices, register bank statements, and send payment follow-ups.</li>\n                        <li><strong>Clean customer invoices:</strong> easy to create, beautiful and full featured invoices.</li>\n                        <li><strong>Automated documents sending:</strong> automatically send your invoices by email or snail mail.</li>\n                        <li><strong>On-the-fly payment reconciliation:</strong> automatic suggestions of outstanding payments when creating invoices.</li>\n                        <li><strong>Banking interface:</strong> with live bank feed synchronization and bank statement import.</li>\n                    </ul>\n                    <p>5) For setup, you will need the following information:</p>\n                    <ul>\n                        <li>Your company's legal name, tax ID, address, and logo.</li>\n                        <li>One bank statement for each bank account you hold.</li>\n                        <li>A list of your customer and supplier payment terms.</li>\n                        <li>A list of common taxes and their rates.</li>\n                        <li>Your Trial Balance (list of accounts and their balances).</li>\n                        <li>Your outstanding invoices, payments, and undeposited funds.</li>\n                    </ul>\n                    <p>Enjoy your Odoo experience,</p>\n                    <div class="mt32">\n                        <img class="signature mb8" src="/web_planner/static/src/img/fabien_signature.png"/>\n                        <address>\n                            For the Odoo Team,<br/>\n                            Fabien Pinckaers, Founder\n                        </address>\n                    </div>\n                </div>\n            </t>\n            <t t-call="web_planner.category">\n                <t t-set="menu_categorytitle">Get started</t>\n                <t t-set="menu_categoryclasses" t-value="'fa fa-flag'"/>\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Your Company</t>\n                    <p class="text-muted">\n                        The first step is to set up your company's information. This is mostly used in printed business documents like orders and invoices.\n                    </p>\n                    <table class="table">\n                    <tr>\n                        <th>Logo</th>\n                        <td>\n                            <img width="150" height="90" alt="set company logo" t-attf-src="data:image/gif;base64, #{company_id.logo}"/>\n                        </td><td>\n                            <a class="fa fa-arrow-right" t-attf-href="#{prepare_backend_url('base.action_res_company_form', 'form')}&amp;id=#{company_id.id}" target="_blank">\n                                Change\n                            </a>\n                        </td>\n                    </tr>\n                    <tr>\n                        <th>Legal Name</th>\n                        <td t-att-class="(company_id.name == 'YourCompany') and 'danger'"><div t-esc="company_id.name"/></td>\n                        <td>\n                            <a class="fa fa-arrow-right" t-attf-href="#{prepare_backend_url('base.action_res_company_form', 'form')}&amp;id=#{company_id.id}" target="_blank">\n                                Change\n                            </a>\n                        </td>\n                    </tr><tr>\n                        <th>Address</th>\n                        <td t-att-class="(not company_id.partner_id.street or not company_id.partner_id.zip) and 'danger'">\n                            <span t-field="company_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;], &quot;no_marker&quot;: True}"/>\n                        </td>\n                        <td>\n                            <a class="fa fa-arrow-right" t-attf-href="#{prepare_backend_url('base.action_res_company_form', 'form')}&amp;id=#{company_id.id}" target="_blank">\n                                Change\n                            </a>\n                        </td>\n                    </tr><tr>\n                        <th>Tax ID</th>\n                        <td t-att-class="(not company_id.vat) and 'danger'">\n                            <span t-field="company_id.vat"/>\n                        </td>\n                        <td>\n                            <a class="fa fa-arrow-right" t-attf-href="#{prepare_backend_url('base.action_res_company_form', 'form')}&amp;id=#{company_id.id}" target="_blank">\n                                Change\n                            </a>\n                        </td>\n                    </tr><tr>\n                        <th>Main Currency</th>\n                        <td><span t-field="company_id.currency_id.display_name"/></td>\n                        <td>\n                            <a class="fa fa-arrow-right" t-attf-href="#{prepare_backend_url('base.action_res_company_form', 'form')}&amp;id=#{company_id.id}" target="_blank">\n                                Change\n                            </a>\n                        </td>\n                    </tr><tr t-if="is_module_installed('sale')">\n                        <th>Terms &amp; Conditions</th>\n                        <td/>\n                        <td>\n                            <a class="fa fa-arrow-right" t-attf-href="#{prepare_backend_url('sale.action_sale_config_settings', 'form')}" target="_blank">\n                                Change\n                            </a>\n                        </td>\n                    </tr><tr>\n                        <th>Payment Terms</th>\n                        <td>\n                            <t t-foreach="payment_term" t-as="term">\n                                <p><t t-esc="term.name"/></p>\n                            </t>\n                        </td><td>\n                            <a id="review_payment_terms" class="fa fa-arrow-right" t-att-href="prepare_backend_url('account.action_payment_term_form')">Review Terms</a>\n                        </td>\n                    </tr>\n                    </table>\n                    <br/>\n                    <div class="alert alert-info info_icon" role="alert">\n                        <span class="fa fa-lightbulb-o fa-lg"/>\n                        <p> Odoo can manage multiple companies, but we suggest to setup everything for your first company before configuring the other ones.</p>\n                    </div>\n                </t>\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Your Bank Accounts</t>\n                    <p>\n                        Once your company information is correct, you should \n                        <strong><a t-att-href="prepare_backend_url('account.action_account_bank_journal_form')">\n                            setup your bank accounts.\n                        </a></strong>\n                    </p><p>\n                        Once your bank accounts are registered, you will be able \n                        to access your statements from the Accounting Dashboard. \n                        The available methods for synchronization are as follows.\n                    </p>\n                    <ul>\n                        <li>Direct connection to your bank</li>\n                        <li>Importing your statements in via a supported file format (QIF, OFX, CODA or CSV format)</li>\n                        <li>Manually enter your transactions using our <a t-att-href="prepare_backend_url('account.action_bank_statement_tree')">fast recording interface</a></li>\n                    </ul>\n                </t>\n\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Chart of Accounts</t>\n                    <t t-if="not is_coa_installed">\n                        <p>Before continuing, you must install the Chart of Account related to your country (or the generic one if your country is not listed).</p>\n                        <a class="btn btn-sm odoo_purple" t-att-href="prepare_backend_url('account.open_account_charts_modules', 'kanban')">Install Chart of Account</a>\n                    </t>\n                    <t t-if="is_coa_installed">\n                        <p>\n                            A <span t-esc="company_id.country_id.name or ''"/> Chart of Accounts has been\n                            installed. You should review it and create any additional accounts.\n                        </p><p>\n                            It's recommended that you do not delete any accounts, even if they are not relevant. Simply make them inactive.\n                        </p><p>\n                            <a class="fa fa-arrow-right" t-att-href="prepare_backend_url('account.action_account_form')">Review the Chart of Accounts</a>\n\n                        </p>\n                    </t>\n                </t>\n\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Taxes</t>\n                    <p class="text-muted">\n                        Odoo has already preconfigured a few taxes according to your country.<br/>Simply review them and check if you need more.\n                    </p>\n                    <p>\n                        <strong>Check the Taxes configuration:</strong>\n                        <ul>\n                            <li><a t-att-href="prepare_backend_url('account.action_tax_form')">Review existing Taxes</a></li>\n                            <li><a t-att-href="prepare_backend_url('account.action_account_config')">Set the default Sales and Purchase taxes</a></li>\n                        </ul>\n                    </p>\n                    <p>\n                        To manage the tax applied when invoicing a Company, Odoo uses the concept of Fiscal Position: they serve to automatically set the right tax and/or account according to the customer country and state.\n                        <ul>\n                            <li><a t-att-href="prepare_backend_url('account.action_account_fiscal_position_form')">Review Fiscal Positions</a></li>\n                        </ul>\n                    </p>\n                </t>\n            </t>\n            <t t-call="web_planner.category">\n                <t t-set="menu_categorytitle">Configure</t>\n                <t t-set="menu_categoryclasses" t-value="'fa-cog'"/>\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Multi Currency</t>\n                    <p>\n                        The multi-currency option allows you to send or receive invoices \n                        in difference currencies, set up foreign bank accounts \n                        and run reports on your foreign financial activities.\n                    </p>\n                    <p>To use the <strong>multi-currency option:</strong>\n                        <ol>\n                            <li>Activate the option in the <a t-att-href="prepare_backend_url('account.action_account_config')">Accounting Settings</a></li>\n                            <li>Review the list of available currencies (from the <a t-att-href="prepare_backend_url('base.action_currency_form')">Configuration menu</a>)</li>\n                        </ol>\n                    </p>\n                    <p>\n                        Most currencies are already created by default. If you plan\n                        to use some of them, you should check their <strong>Active</strong>\n                        field.\n                    </p>\n                    <div class="alert alert-info info_icon" role="alert">\n                        <span class="fa fa-lightbulb-o fa-lg"/>\n                        <p>Exchange rates can be automatically updated once a day from <strong>Yahoo Finance</strong> or the <strong>European Central Bank</strong>. You can activate this feature in the bottom of the <a t-att-href="prepare_backend_url('account.action_account_config')">Accounting Settings</a>.</p>\n                    </div>\n                </t>\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Your Customers</t>\n                    <p class="text-muted">\n                        Unless you are starting a new business, you probably have a list of customers and vendors you'd like to import.\n                    </p>\n                    <div class="row">\n                        <div class="col-md-6">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <span class="fa" data-icon=""/>\n                                        <strong> Create manually</strong><br/>\n                                        <span class="small">&lt; 200 contacts</span>\n                                    </span>\n                                </div>\n                                <div class="panel-body">\n                                    <p>\n                                        If you have less than 200 contacts, we recommend you\n                                        create them manually.\n                                    </p>\n                                    <ul>\n                                        <li>\n                                            <a t-att-href="prepare_backend_url('base.action_partner_form','kanban')">Create Customers</a>\n                                        </li><li>\n                                            <a t-att-href="prepare_backend_url('base.action_partner_supplier_form','kanban')">Create Vendors</a>, if accounting or purchase is installed\n                                        </li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-6">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <span class="fa" data-icon=""/>\n                                        <strong>Import</strong><br/>\n                                        <span class="small">&gt; 200 contacts</span>\n                                    </span>\n                                </div>\n                                <div class="panel-body">\n                                    <p>\n                                        We can handle the whole import process\n                                        for you: simply send your Odoo project\n                                        manager a CSV file containing all your\n                                        data.\n                                    </p><p>\n                                        If you want to do it yourself:\n                                    </p>\n                                    <ul>\n                                        <li>Download the <a href="/base_import/static/csv/customers.xls">Excel template</a></li>\n                                        <li>Import using the "Import" button on the top left corner of <a t-att-href="prepare_backend_url('base.action_partner_form','list')">the customer list</a></li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </t>\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Your Products</t>\n                    <p>\n                        A product in Odoo is something you sell or buy \n                        whether or not it is goods, consumables, or services.\n                        Choose how you want to create your products:\n                    </p>\n\n                    <div class="row">\n                        <div class="col-md-6">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <span class="fa" data-icon=""/>\n                                        <strong> Create manually</strong><br/>\n                                        <span class="small">Recommended if &lt;100 products</span>\n                                    </span>\n                                </div>\n                                <div class="panel-body">\n                                    <ul>\n                                        <li><a t-att-href="prepare_backend_url('product.product_template_action', 'form')">Create your products</a></li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-6">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <span class="fa" data-icon=""/>\n                                        <strong>Import a file</strong><br/>\n                                        <span class="small">Recommended if &gt;100 products</span>\n                                    </span>\n                                </div>\n                                <div class="panel-body">\n                                    <p>\n                                        We can handle the whole import process\n                                        for you: simply send your Odoo project\n                                        manager a CSV file containing all your\n                                        products.\n                                    </p><p>\n                                        If you want to do it yourself:\n                                    </p>\n                                    <ul>\n                                        <li>Download the <a href="/base_import/static/csv/products.xls">Excel template</a></li>\n                                        <li>Import using the "Import" button on the top left corner of <a t-att-href="prepare_backend_url('product.product_template_action','list')">the product list</a></li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </t>\n\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Account Balances</t>\n                    <p>\n                        Once you have created your chart of accounts, you will need to update your account balances.\n                    </p>\n                    <p>\n                        <ul>\n                            <li>In your old accounting software, print a trial balance</li>\n                            <li>In Odoo, <a t-att-href="prepare_backend_url('account.action_move_journal_line')">create a journal entry</a> to set the balance of all of your accounts.</li>\n                        </ul>\n                    </p>\n                    <div class="alert alert-info info_icon" role="alert">\n                        <span class="fa fa-lightbulb-o fa-lg"/>\n                        <p>\n                            It's common practice to change your accounting software \n                            at the end of a fiscal year. This allows you to have less \n                            data to import and balances to set. If you plan to do so, \n                            we recommend you start using Odoo for invoicing and payments \n                            now, and then move all other accounting transactions at a later time.\n                        </p>\n                    </div>\n                </t>\n\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Outstanding Transactions</t>\n                    <p class="text-muted">\n                        If you want to be able to send your customers their statements \n                        from Odoo, you first need to record all outstanding transactions \n                        in the payable and receivable accounts. These would be invoices \n                        that have not been paid or payments that have not been reconciled.\n                    </p><p>\n                        Registering outstanding invoices and payments can be a huge undertaking, \n                        but you can start using Odoo without it by:\n                    </p>\n                    <ul>\n                        <li>Sending customer statements (outstanding invoices) manually during the transition period</li>\n                        <li>Registering payments related to outstanding invoices separately in a different account (e.g. Account Receivables 2014)</li>\n                    </ul>\n                    <p>\n                        If you want to be able to send customer statements from Odoo, you must:\n                    </p>\n                    <div class="row">\n                        <div class="col-md-6">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <div class="panel-title">\n                                        <strong>1. Register Outstanding Invoices</strong>\n                                    </div>\n                                 </div>\n                                 <div class="panel-body">\n                                    <p>First, register any outstanding customer invoices and vendor bills:</p>\n                                    <ul>\n                                        <li><a t-att-href="prepare_backend_url('account.action_invoice_tree1')">Customer Invoices</a></li>\n                                        <li><a t-att-href="prepare_backend_url('account.action_invoice_tree2')">Vendor Bills</a></li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-6">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <div class="panel-title">\n                                        <strong>2. Register Unmatched Payments</strong>\n                                    </div>\n                                 </div>\n                                 <div class="panel-body">\n                                    <p>\n                                        Next, register any unmatched payments:<br/>\n                                        <ul>\n                                            <li><a t-att-href="prepare_backend_url('account.action_account_payments')">Register Payments</a></li>\n                                        </ul>\n                                    </p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </t>\n\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Extra Features</t>\n                    <p class="text-muted">\n                        Odoo Accounting has many extra-features:\n                    </p>\n                    <div class="row o_planner_row_apps">\n                        <div class="text-center col-md-4">\n                            <span class="fa fa-building-o fa-4x"/>\n                            <h3><strong>Assets Management</strong></h3>\n                            <p>Manage your various fixed assets, such as buildings, machinery, materials, cars, etc..., and calculate their associated depreciation over time.</p>\n                            <a t-att-href="prepare_backend_url('base.open_module_tree', 'form', 'account_asset')" class="btn odoo_purple">\n                                <span class="fa fa-arrow-circle-o-down"/> Install Now\n                            </a>\n                        </div>\n                        <div class="text-center col-md-4">\n                            <span class="fa fa-tasks fa-4x"/>\n                            <h3><strong>Revenue Recognition</strong></h3>\n                            <p>Use in conjunction with contracts to calculate your monthly revenue for multi-month contracts.</p>\n                            <a t-att-href="prepare_backend_url('base.open_module_tree', 'form', 'account_deferred_revenue')" class="btn odoo_purple">\n                                <span class="fa fa-arrow-circle-o-down"/> Install Now\n                            </a>\n                        </div>\n                        <div class="text-center col-md-4">\n                            <span class="fa fa-university fa-4x"/>\n                            <h3><strong>Deposit Tickets</strong></h3>\n                            <p>Simplify your cash, checks, or credit cards deposits with an integrated batch payment function.</p>\n                            <a t-att-href="prepare_backend_url('base.open_module_tree', 'form', 'account_batch_deposit')" class="btn odoo_purple">\n                                <span class="fa fa-arrow-circle-o-down"/> Install Now\n                            </a>\n                        </div>\n                    </div>\n                    <div class="row o_planner_row_apps">\n                        <div class="text-center col-md-4">\n                            <span class="fa fa-money fa-4x"/>\n                            <h3><strong>Expenses</strong></h3>\n                            <p>Manage your employee expenses, from encoding, to payments and reporting.</p>\n                            <a t-att-href="prepare_backend_url('base.open_module_tree', 'form', 'hr_expense')" class="btn odoo_purple">\n                                <span class="fa fa-arrow-circle-o-down"/> Install Now\n                            </a>\n                        </div>\n                        <div class="text-center col-md-4">\n                            <span class="fa fa-shopping-cart fa-4x"/>\n                            <h3><strong>Purchases</strong></h3>\n                            <p>Validate purchase orders and control vendor bills by departments.</p>\n                            <a t-att-href="prepare_backend_url('base.open_module_tree', 'form', 'purchase')" class="btn odoo_purple">\n                                <span class="fa fa-arrow-circle-o-down"/> Install Now\n                            </a>\n                        </div>\n                        <div class="text-center col-md-4">\n                            <span class="fa fa-copy fa-4x"/>\n                            <h3><strong>Contracts &amp; Subscriptions</strong></h3>\n                            <p>Manage time &amp; material contracts or fixed-price recurring subscriptions.</p>\n                            <a t-att-href="prepare_backend_url('base.open_module_tree', 'form', 'sale_subscription')" class="btn odoo_purple">\n                                <span class="fa fa-arrow-circle-o-down"/> Install Now\n                            </a>\n                        </div>\n                    </div>\n                </t>\n            </t>\n            <t t-call="web_planner.category">\n                <t t-set="menu_categorytitle">Use</t>\n                <t t-set="menu_categoryclasses" t-value="'fa-hand-o-up'"/>\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Invite Users</t>\n                    <p>\n                        When inviting users, you will need to define which access rights they are allowed to have. \n                        This is done by assigning a role to each user.\n                    </p>\n                    <p><strong>There are three different levels of access rights in Odoo:</strong></p>\n                    <div class="row">\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Billing</strong> (Limited access)\n                                    </span>\n                                 </div>\n                                 <div class="panel-body">\n                                    <p>These users handle billing specifically.</p>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Advisor</strong> (Full access)\n                                    </span>\n                                 </div>\n                                 <div class="panel-body">\n                                    <p>\n                                        The Advisors have full access to the Accounting application, \n                                        plus access to miscellaneous operations such as salary and asset management.\n                                    </p>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Accountant</strong> (Advanced access)\n                                    </span>\n                                 </div>\n                                 <div class="panel-body">\n                                    <p>\n                                        This role is best suited for managing the day to day accounting operations:\n                                        <ul>\n                                            <li>Recording invoices</li>\n                                            <li>Managing bank fees</li>\n                                            <li>Reconciling journal entries</li>\n                                        </ul>\n                                    </p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    <br/>\n                    <div class="row">\n                        <div class="col-md-4">\n                            <strong>Next action:</strong><br/>\n                            <a t-att-href="prepare_backend_url('base.action_res_users')" class="btn odoo_purple">\n                                <span class="fa"/> Invite Your Users\n                            </a>\n                        </div>\n                    </div>\n                </t>\n\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Customer Flow</t>\n                    <p><strong>Test the following three scenarios in order to assist you in familiarizing yourself with Odoo:</strong></p>\n                    <div class="row">\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Invoice payment by Wire Transfer</strong>\n                                    </span>\n                                </div>\n                                <div class="panel-body">\n                                    <p>\n                                        <strong>Create a Customer Invoice</strong>\n                                    </p>\n                                    <p>\n                                        <strong>Record Bank Statement (or import file)</strong><br/>\n                                        Depending on the volume of your transactions, you should be recording your bank statement every week to several times a day.\n                                    </p>\n                                    <p><strong>Reconcile Bank Statement</strong></p>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Invoice payment by Check</strong>\n                                    </span>\n                                 </div>\n                                 <div class="panel-body">\n                                    <p><strong>Create a Customer Invoice</strong></p>\n                                    <p>\n                                        <strong>Record a payment by check on the Invoice</strong><br/>\n                                        Simply click on the 'Pay' button.\n                                    </p>\n                                    <p><strong>Create a Deposit Ticket</strong><br/>\n                                        This allows you to record the different payments that constitute your bank deposit. (You may need to <a t-att-href="prepare_backend_url('account.action_account_config')">activate this feature</a> first)\n                                    </p>\n                                    <p><strong>Record Bank Statement</strong></p>\n                                    <p>\n                                        <strong>Reconcile with existing transaction</strong><br/>\n                                        In this case, Odoo should automatically match the bank statement with the previously recorded check transaction.\n                                    </p>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Customer follow-up</strong>\n                                    </span>\n                                </div>\n                                <div class="panel-body">\n                                    <p><strong>Reconcile your Bank Statements</strong></p>\n                                    <p><strong>Check unpaid invoices</strong><br/>\n                                         Run an <i>Aged Receivable report</i> and check which customers still owe you money.\n                                    </p>\n                                    <p><strong>Send follow-up letters</strong></p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="alert alert-info info_icon" role="alert">\n                        <span class="fa fa-lightbulb-o fa-lg"/>\n                        <p>The Deposit Ticket module can also be used to settle credit card batch made of multiple transactions.</p>\n                    </div>\n                </t>\n\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">Vendor Flow</t>\n                    <p><strong>Test the following three scenarios in order to assist you in familiarizing yourself with Odoo:</strong></p>\n                    <div class="row">\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Record your Bills</strong>\n                                    </span>\n                                 </div>\n                                 <div class="panel-body">\n                                    <p><strong>Create the bill in Odoo</strong><br/> with a proper due date, and create the vendor if it doesnt' exist yet.</p>\n                                    <p><strong>Cash transactions</strong><br/> (for which there is no invoice or bill), should be entered directly into your Cash Registers bank account.</p>\n                                    <p><strong>Validate the bill</strong><br/> after encoding the products and taxes.</p>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Pay your bills</strong>\n                                    </span>\n                                </div>\n                                <div class="panel-body">\n                                    <p>\n                                        <strong>Mark the bills to pay</strong><br/>\n                                        Group or filter your bills to see those due in the next week, then open each bill individually, click on <strong>'Pay'</strong> and select the payment method you prefer.\n                                    </p>\n                                    <p>\n                                        <strong>Print checks</strong><br/>\n                                        From the Vendor Payments list, select those you want to pay and click on Print Check (you may first need to activate the check feature in the <a t-att-href="prepare_backend_url('account.action_account_config')">Accounting Settings</a>)\n                                    </p>\n                                    <p>\n                                        <strong>Or generate payment orders</strong><br/>\n                                        Create a Payment Order and select the bills you'd like to pay as Entry lines (only the validated bills will appear).\n                                    </p>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-md-4">\n                            <div class="panel panel-success">\n                                <div class="panel-heading">\n                                    <span class="panel-title">\n                                        <strong>Reconcile Bank Statements</strong>\n                                    </span>\n                                </div>\n                                <div class="panel-body">\n                                    <p>Odoo should do most of the reconciliation work automatically, so you'll only need to review a few of them when a <strong>'Reconcile Items'</strong> button appears on your Vendor Bills dash.</p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </t>\n                <t t-call="web_planner.page">\n                    <t t-set="page_title">End</t>\n                    <t t-set="hide_title" t-value="True"/>\n                    <t t-set="hide_from_menu" t-value="True"/>\n                    <t t-set="hide_mark_as_done" t-value="True"/>\n                    <h1 class="text-center o_planner_trophy" data-icon=""/>\n                    <div class="text-center">\n                        <h1>Congratulations, you're done!</h1>\n                        <h3>We hope this tool helped you implement our accounting application.</h3>\n                        <h4>Don't hesitate to <a href="mailto:info@odoo.com?subject=Accounting%20Planner" target="_blank">send us an email</a> to describe<br/> your experience or to suggest improvements !</h4>\n                        <p><strong>-The Odoo Team</strong></p>\n                        <img src="/web_planner/static/src/img/odoo_logo.png"/>\n                    </div>\n                </t>\n            </t>\n        </t>\n    </t>\n\n    	account/views/web_planner_data.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
515	account.journal.dashboard.kanban	account.journal	\N	16	kanban	<?xml version="1.0"?>\n<kanban create="false" class="oe_background_grey o_kanban_dashboard o_account_kanban">\n                <field name="id"/>\n                <field name="name"/>\n                <field name="type"/>\n                <field name="color"/>\n                <field name="show_on_dashboard"/>\n                <field name="kanban_dashboard"/>\n                <templates>\n                    <t t-name="kanban-box">\n                        <div t-attf-class="#{kanban_color(record.color.raw_value)}">\n                            <t t-value="JSON.parse(record.kanban_dashboard.raw_value)" t-set="dashboard"/>\n                            <t t-value="record.type.raw_value" t-set="journal_type"/>\n                            <t t-call="JournalTop"/>\n                            <div class="container o_kanban_card_content">\n                                <div class="row">\n                                    <t t-if="(journal_type == 'bank' || journal_type == 'cash')" t-call="JournalBodyBankCash"/>\n                                    <t t-if="journal_type == 'sale' || journal_type == 'purchase'" t-call="JournalBodySalePurchase"/>\n                                    <t t-if="journal_type == 'general' || journal_type == 'situation'">\n                                        <div class="col-xs-6 o_kanban_primary_left">\n                                            <button type="object" name="open_action" context="{'action_name': 'action_move_journal_line', 'view_no_maturity': 1}" class="btn btn-primary btn-sm">\n                                                <span>Journal Entries</span>\n                                            </button>\n                                        </div>\n                                    </t>\n                                </div>\n                                <t t-if="journal_type == 'bank' || journal_type == 'cash' || journal_type == 'sale' || journal_type == 'purchase'" t-call="JournalBodyGraph"/>\n                            </div><div class="container o_kanban_card_manage_pane">\n                                <t t-call="JournalManage"/>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalTop">\n                        <div t-attf-class="o_kanban_card_header">\n                            <div class="o_kanban_card_header_title">\n                                <div class="o_primary">\n                                    <a type="object" name="open_action"><field name="name"/></a>\n                                </div>\n                                <div class="o_secondary" t-att-title="dashboard.title">\n                                    <field name="type"/>\n                                </div>\n                            </div>\n                            <div class="o_kanban_manage_button_section">\n                                <a class="o_kanban_manage_toggle_button" href="#"><i class="fa fa-ellipsis-v"/></a>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalManage">\n\n                        <!-- For bank and cash -->\n                        <div t-if="journal_type == 'bank' || journal_type == 'cash'" class="row">\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_view">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>View</span>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action">\n                                        <t t-if="journal_type == 'bank'">Bank Statements</t>\n                                        <t t-if="journal_type == 'cash'">Cash Statements</t>\n                                    </a>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action_with_context" context="{'action_name': 'action_bank_statement_line', 'search_default_journal': True}">Search Operations</a>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action" context="{'action_name': 'action_account_moves_all_a'}" groups="base.group_no_one">Journal Items</a>\n                                </div>\n                            </div>\n\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_new">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>New</span>\n                                </div>\n                                <div name="bank_cash_commands">\n                                    <t t-if="journal_type == 'bank'">\n                                        <a type="object" name="create_bank_statement">Transaction</a>\n                                    </t>\n                                    <t t-if="journal_type == 'cash'">\n                                        <a type="object" name="create_cash_statement">Transaction</a>\n                                    </t>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_spend_money">Send Money</a>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_collect_money">Receive Money</a>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_transfer_money">Internal Transfer</a>\n                                </div>\n                            </div>\n\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_reconciliation">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>Reconciliation</span>\n                                </div>\n                                <div>\n                                    <a t-if="dashboard.number_to_reconcile &gt; 0" type="object" name="action_open_reconcile">Reconcile</a>\n                                    <span t-if="dashboard.number_to_reconcile == 0" class="text-muted">Nothing to Reconcile</span>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action_with_context" context="{'action_name': 'action_account_reconcile_model', 'use_domain': True}" groups="account.group_account_manager">Reconciliation Models</a>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- For purchase and sale -->\n                        <div t-if="journal_type == 'purchase' || journal_type == 'sale'" class="row">\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_view">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>View</span>\n                                </div>\n                                <div>\n                                    <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'use_domain': [('type', '=', 'out_invoice')]}">Invoices</a>\n                                    <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'use_domain': [('type', '=', 'in_invoice')]}">Bills</a>\n                                </div>\n                                <div>\n                                    <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'use_domain': [('type', '=', 'out_refund')], 'invoice_type': 'refund'}">Credit Notes</a>\n                                    <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'use_domain': [('type', '=', 'in_refund')], 'invoice_type': 'refund'}">Credit Notes</a>\n                                </div>\n                                <div>\n                                    <a type="object" name="action_open_reconcile">Payments Matching</a>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action" context="{'action_name': 'action_account_moves_all_a'}" groups="base.group_no_one">Journal Items</a>\n                                </div>\n                            </div>\n\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_new">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>New</span>\n                                </div>\n                                <div>\n                                    <a type="object" name="action_create_new">\n                                        <span t-if="journal_type == 'sale'">Invoice</span>\n                                        <span t-if="journal_type == 'purchase'">Bill</span>\n                                    </a>\n                                </div>\n                                <div>\n                                    <a type="object" name="action_create_new" context="{'refund':True}">\n                                        <span t-if="journal_type == 'sale'">Credit Note</span>\n                                        <span t-if="journal_type == 'purchase'">Credit Note Bill</span>\n                                    </a>\n                                </div>\n                            </div>\n\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_reports">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>Reporting</span>\n                                </div>\n                                <div>\n                                    <a t-if="journal_type == 'sale'" type="action" name="210" groups="account.group_account_manager">Invoices Analysis</a>\n                                    <a t-if="journal_type == 'purchase'" type="action" name="209" groups="account.group_account_manager">Bills Analysis</a>\n                                </div>\n                            </div>\n                        </div>\n\n                        <!-- For general and situation -->\n                        <div t-if="journal_type == 'general' || journal_type == 'situation'" class="row">\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_view">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>View</span>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action" context="{'action_name': 'action_move_journal_line', 'view_no_maturity': 1}">Journal Entries</a>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action" context="{'action_name': 'action_move_journal_line', 'search_default_toreview': 1, 'view_no_maturity': 1}">Entries to Review</a>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action" context="{'action_name': 'action_account_moves_all_a'}" groups="base.group_no_one">Journal Items</a>\n                                </div>\n                            </div>\n\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_new">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>New</span>\n                                </div>\n                                <div>\n                                    <a type="object" name="action_create_new">Journal Entry</a>\n                                </div>\n                            </div>\n\n                             <div class="col-xs-4 o_kanban_card_manage_section o_kanban_manage_operations">\n                                <div class="o_kanban_card_manage_title">\n                                    <span>Operations</span>\n                                </div>\n                                <div>\n                                    <a type="object" name="open_action_with_context" context="{'action_name': 'action_validate_account_move', 'search_default_journal': True}">Post All Entries</a>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div t-if="widget.editable" class="o_kanban_card_manage_settings row">\n                            <div class="col-xs-8">\n                                <ul class="oe_kanban_colorpicker" data-field="color"/>\n                            </div>\n                        </div>\n\n                        <div groups="account.group_account_manager" class="row o_kanban_card_settings">\n                            <div class="col-xs-6">\n                                <field name="show_on_dashboard" widget="boolean_favorite"/>\n                            </div>\n                            <div class="col-xs-6 text-right">\n                                <a t-if="widget.editable" type="edit">Settings</a>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalBodyBankCash">\n                        <!-- On the left, display :\n                            - A button corresponding to the bank_statements_source, if it wasn't configured, a button for each of them\n                            - If there are statements to reconcile, a link to reconcile them -->\n                        <div class="col-xs-6 o_kanban_primary_left">\n                            <t t-if="dashboard.number_to_reconcile &gt; 0">\n                                <button type="object" name="action_open_reconcile" class="btn btn-primary btn-sm"> Reconcile <t t-esc="dashboard.number_to_reconcile"/> Items</button>\n                            </t>\n                            <t t-if="journal_type == 'bank'">\n                                <div name="bank_journal_default_cta" t-if="dashboard.bank_statements_source == 'undefined'">\n                                    <button t-if="dashboard.number_to_reconcile == 0" type="object" name="create_bank_statement" class="btn btn-primary btn-sm">New Statement</button>\n                                    <a t-if="dashboard.number_to_reconcile &gt; 0" type="object" name="create_bank_statement" class="oe_inline">New Statement</a>\n                                </div>\n                                <div name="bank_journal_cta" t-if="dashboard.bank_statements_source != 'undefined'">\n                                    <button t-if="dashboard.bank_statements_source == 'manual' &amp;&amp; dashboard.number_to_reconcile == 0" type="object" name="create_bank_statement" class="btn btn-primary btn-sm">New Statement</button>\n                                    <a t-if="dashboard.bank_statements_source == 'manual' &amp;&amp; dashboard.number_to_reconcile &gt; 0" type="object" name="create_bank_statement" class="oe_inline">New Statement</a>\n                                </div>\n                            </t>\n                            <t t-if="dashboard.number_to_reconcile &gt; 0">\n                                <a t-if="journal_type == 'cash'" type="object" name="create_cash_statement" class="oe_inline">New Transactions</a>\n                            </t>\n                            <t t-if="dashboard.number_to_reconcile == 0">\n                                <button t-if="journal_type == 'cash'" type="object" name="create_cash_statement" class="btn btn-primary btn-sm">New Transactions</button>\n                            </t>\n                        </div>\n                        <!-- On the right, show other common informations/actions -->\n                        <div class="col-xs-6 o_kanban_primary_right">\n                            <div class="row">\n                                <div class="col-xs-6">\n                                    <span title="Balance in Odoo">Balance in GL</span>\n                                </div>\n                                <div class="col-xs-6 text-right">\n                                    <span><t t-esc="dashboard.account_balance"/></span>\n                                </div>\n                            </div>\n                            <t t-if="dashboard.last_balance != dashboard.account_balance">\n                                <div class="row" name="latest_statement">\n                                    <div class="col-xs-6">\n                                        <span title="Latest Statement">Latest Statement</span>\n                                    </div>\n                                    <div class="col-xs-6 text-right">\n                                        <span><t t-esc="dashboard.last_balance"/></span>\n                                    </div>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-name="JournalBodySalePurchase" id="account.JournalBodySalePurchase">\n                        <div class="col-xs-6 o_kanban_primary_left">\n                            <t t-if="journal_type == 'sale'">\n                                <button type="object" name="action_create_new" class="btn btn-primary btn-sm o_invoice_new">\n                                    <span>New Invoice</span>\n                                </button>\n                            </t>\n                            <t t-if="journal_type == 'purchase'">\n                                <button type="object" name="action_create_new" class="btn btn-primary btn-sm">\n                                    <span>New Bill</span>\n                                </button>\n                            </t>\n                        </div>\n                        <div class="col-xs-6 o_kanban_primary_right">\n                            <div class="row">\n                                <div class="col-xs-6">\n                                    <a type="object" name="open_action" context="{'search_default_draft': '1'}">\n                                        <span t-if="journal_type == 'sale'" title="Invoices to validate"><t t-esc="dashboard.number_draft"/> Invoices to validate</span>\n                                        <span t-if="journal_type == 'purchase'" title="Draft bills"><t t-esc="dashboard.number_draft"/> Draft bills</span>\n                                    </a>\n                                </div>\n                                <div class="col-xs-6 text-right">\n                                    <span><t t-esc="dashboard.sum_draft"/></span>\n                                </div>\n                            </div>\n                            <div class="row">\n                                <div class="col-xs-6">\n                                    <a type="object" t-if="journal_type == 'sale'" name="open_action" context="{'search_default_unpaid':1}" id="account_dashboard_sale_pay_link">\n                                        <t t-esc="dashboard.number_waiting"/> Awaiting payments\n                                    </a>\n\n                                    <a type="object" t-if="journal_type == 'purchase'" name="open_action" context="{'search_default_unpaid':1}" id="account_dashboard_purchase_pay_link">\n                                        <t t-esc="dashboard.number_waiting"/> Payments to do\n                                    </a>\n                                </div>\n                                <div class="col-xs-6 text-right">\n                                    <span><t t-esc="dashboard.sum_waiting"/></span>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                    <t t-name="JournalBodyGraph">\n                        <field name="kanban_dashboard_graph" t-att-graph_type="_.contains(['cash','bank'],journal_type) ? 'line' : 'bar'" widget="dashboard_graph"/>\n                    </t>\n            </templates>\n            </kanban>\n        	account/views/account_journal_dashboard_view.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
516	Portal layout : invoice menu entries	\N	account.portal_my_home_menu_invoice	30	qweb	<?xml version="1.0"?>\n<data name="Portal layout : invoice menu entries" inherit_id="portal.portal_layout" priority="30">\n        <xpath expr="//ol[hasclass('o_portal_submenu')]" position="inside">\n            <li t-if="page_name == 'invoice'" class="active">\n                <a t-if="invoice" t-attf-href="/my/invoices?{{ keep_query() }}">Invoices</a>\n                <t t-else="">Invoices</t>\n            </li>\n            <li t-if="invoice">\n                <t t-esc="invoice.number"/>\n            </li>\n        </xpath>\n    </data>\n\n    	account/views/account_portal_templates.xml	307	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	extension	t	1	1
517	Portal My Home : invoice entries	\N	account.portal_my_home_invoice	30	qweb	<?xml version="1.0"?>\n<data name="Portal My Home : invoice entries" inherit_id="portal.portal_my_home" priority="30">\n        <xpath expr="//ul[hasclass('o_portal_docs')]" position="inside">\n            <li t-if="invoice_count" class="list-group-item">\n                <span class="badge" t-esc="invoice_count"/>\n                <a href="/my/invoices">Invoices</a>\n            </li>\n        </xpath>\n    </data>\n\n    	account/views/account_portal_templates.xml	309	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	extension	t	1	1
518	My Invoices and Payments	\N	account.portal_my_invoices	16	qweb	<?xml version="1.0"?>\n<t name="My Invoices and Payments" t-name="account.portal_my_invoices">\n      <t t-call="portal.portal_layout">\n        <h3>Invoices\n            <t t-call="portal.portal_searchbar"/>\n        </h3>\n        <t t-if="not invoices">\n            <p>There are currently no invoices and payments for your account.</p>\n        </t>\n        <div t-if="invoices" class="panel panel-default">\n            <div class="table-responsive"><table class="table table-hover o_portal_my_doc_table">\n                <thead>\n                  <tr class="active">\n                    <th>Invoice #</th>\n                    <th>Invoice Date</th>\n                    <th class="hidden-xs">Due Date</th>\n                    <th/>\n                    <th>Amount Due</th>\n                  </tr>\n                </thead>\n                <t t-foreach="invoices" t-as="invoice">\n                    <tr>\n                        <td>\n                            <a t-attf-href="/my/invoices/#{invoice.id}" t-att-title="invoice.number"><t t-esc="invoice.number"/></a>\n                        </td>\n                        <td><span t-field="invoice.date_invoice"/></td>\n                        <td class="hidden-xs"><span t-field="invoice.date_due"/></td>\n                        <td>\n                            <t t-if="invoice.state == 'open'">\n                                <span class="label label-info"><i class="fa fa-fw fa-clock-o"/><span class="hidden-xs"> Waiting for Payment</span></span>\n                            </t>\n                            <t t-if="invoice.state == 'paid'">\n                                <span class="label label-default"><i class="fa fa-fw fa-check"/><span class="hidden-xs"> Paid</span></span>\n                            </t>\n                            <t t-if="invoice.state == 'cancel'">\n                                <span class="label label-default"><i class="fa fa-fw fa-remove"/><span class="hidden-xs"> Cancelled</span></span>\n                            </t>\n                        </td>\n                        <td><span t-esc="-invoice.residual if invoice.type == 'out_refund' else invoice.residual" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/></td>\n                    </tr>\n                </t>\n            </table></div>\n            <div t-if="pager" class="o_portal_pager text-center">\n                <t t-call="portal.pager"/>\n            </div>\n        </div>\n      </t>\n    </t>\n\n    	account/views/account_portal_templates.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
678	stock.picking.kanban	stock.picking	\N	16	kanban	<?xml version="1.0"?>\n<kanban class="o_kanban_mobile">\n                    <field name="name"/>\n                    <field name="partner_id"/>\n                    <field name="location_dest_id"/>\n                    <field name="state"/>\n                    <field name="date"/>\n                    <templates>\n                        <t t-name="kanban-box">\n                            <div t-attf-class="oe_kanban_card oe_kanban_global_click">\n                                <div class="o_kanban_record_top mb8">\n                                    <div class="o_kanban_record_headings">\n                                        <strong class="o_kanban_record_title"><span><t t-esc="record.name.value"/></span></strong>\n                                    </div>\n                                    <strong>\n                                            <field name="state" widget="label_selection" options="{'classes': {'draft': 'default', 'cancel': 'default', 'none': 'danger', 'waiting': 'warning', 'confirmed': 'warning', 'partially_available': 'warning', 'done': 'success'}}"/>\n                                    </strong>\n                                </div>\n                                <div class="o_kanban_record_bottom">\n                                    <div class="oe_kanban_bottom_left">\n                                        <t t-esc="record.partner_id.value"/>\n                                    </div>\n                                    <div class="oe_kanban_bottom_right">\n                                        <t t-esc="record.date.value and record.date.value.split(' ')[0] or False"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>\n            	stock/views/stock_picking_views.xml	\N	\N	2020-03-20 13:33:59.668484	2020-03-20 13:33:59.668484	primary	t	1	1
519	Invoice Portal Template	\N	account.portal_invoice_page	16	qweb	<?xml version="1.0"?>\n<t name="Invoice Portal Template" t-name="account.portal_invoice_page">\n        <t t-call="portal.portal_layout">\n            <div class="container">\n                <div class="panel panel-default">\n                    <div class="panel-heading">\n                        <div class="row">\n                            <div class="col-md-6">\n                                <h4>\n                                    <t t-call="portal.record_pager"/>\n                                    <span t-if="invoice.type == 'out_invoice' and (invoice.state == 'open' or invoice.state == 'paid')">Invoice</span>\n                                    <span t-if="invoice.type == 'out_invoice' and invoice.state == 'draft'">Draft Invoice</span>\n                                    <span t-if="invoice.type == 'out_invoice' and invoice.state == 'cancel'">Cancelled Invoice</span>\n                                    <span t-if="invoice.type == 'out_refund'">Credit Note</span>\n                                    <span t-if="invoice.type == 'in_refund'">Vendor Credit Note</span>\n                                    <span t-if="invoice.type == 'in_invoice'">Vendor Bill</span>\n                                    <span t-field="invoice.number"/>\n                                </h4>\n                            </div>\n                            <div class="col-md-6 col-sm-6 col-xs-12 hidden-print" id="o_portal_account_actions">\n                                <a target="_blank" t-att-href="'/my/invoices/pdf/%s?%s' % (invoice.id, keep_query())" class="pull-right" title="Download">\n                                    <i class="fa fa-download fa-2x" aria-hidden="true"/>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="panel-body">\n                        <t t-if="error or warning" t-call="account.portal_invoice_error"/>\n                        <t t-if="success and (not error and not warning)" t-call="account.portal_invoice_success"/>\n                        <t t-call="account.portal_invoice_report"/>\n                    </div>\n                </div>\n            </div>\n            <div class="oe_structure mb32"/>\n        </t>\n    </t>\n\n    	account/views/account_portal_templates.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
520	Invoice Portal Report	\N	account.portal_invoice_report	16	qweb	<?xml version="1.0"?>\n<t name="Invoice Portal Report" t-name="account.portal_invoice_report">\n        <div class="row">\n            <div class="col-xs-5" name="customer_address">\n                <strong>Customer Address</strong>\n                <address t-field="invoice.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                <div t-if="invoice.partner_id.vat" class="mt16">VAT: <span t-field="invoice.partner_id.vat"/></div>\n            </div>\n        </div>\n\n        <div class="row mt32 mb32">\n            <div class="col-xs-2" t-if="invoice.name">\n                <strong>Description:</strong>\n                <p t-field="invoice.name"/>\n            </div>\n            <div class="col-xs-2" t-if="invoice.date_invoice">\n                <strong>Invoice Date:</strong>\n                <p t-field="invoice.date_invoice"/>\n            </div>\n            <div class="col-xs-2" t-if="invoice.date_due and invoice.type == 'out_invoice' and (invoice.state == 'open' or invoice.state == 'paid')">\n                <strong>Due Date:</strong>\n                <p t-field="invoice.date_due"/>\n            </div>\n            <div class="col-xs-2" t-if="invoice.origin">\n                <strong>Source:</strong>\n                <p t-field="invoice.origin"/>\n            </div>\n            <div class="col-xs-2" t-if="invoice.partner_id.ref">\n                <strong>Customer Code:</strong>\n                <p t-field="invoice.partner_id.ref"/>\n            </div>\n            <div name="reference" class="col-xs-2" t-if="invoice.reference">\n                <strong>Reference:</strong>\n                <p t-field="invoice.reference"/>\n            </div>\n        </div>\n\n        <!-- Is there a discount on at least one line? -->\n        <t t-set="display_discount" t-value="any([l.discount for l in invoice.invoice_line_ids])"/>\n\n        <table class="table table-condensed">\n            <thead>\n                <tr>\n                    <th>Description</th>\n                    <th class="hidden">Source Document</th>\n                    <th class="text-right">Quantity</th>\n                    <th class="text-right">Unit Price</th>\n                    <th t-if="display_discount" class="text-right">Disc.(%)</th>\n                    <th class="text-right">Taxes</th>\n                    <th class="text-right">Amount</th>\n                </tr>\n            </thead>\n            <tbody class="o_portal_report_tbody">\n                <tr t-foreach="invoice.invoice_line_ids" t-as="l">\n                    <td><span t-field="l.name"/></td>\n                    <td class="hidden"><span t-field="l.origin"/></td>\n                    <td class="text-right">\n                        <span t-field="l.quantity"/>\n                        <span t-field="l.uom_id" groups="product.group_uom"/>\n                    </td>\n                    <td class="text-right">\n                        <span t-field="l.price_unit"/>\n                    </td>\n                    <td t-if="display_discount" class="text-right">\n                        <span t-field="l.discount"/>\n                    </td>\n                    <td class="text-right">\n                        <span t-esc="', '.join(map(lambda x: (x.description or x.name), l.invoice_line_tax_ids))"/>\n                    </td>\n                    <td class="text-right" id="subtotal">\n                        <span t-field="l.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>\n                    </td>\n                </tr>\n                <tr t-foreach="range(max(5-len(invoice.invoice_line_ids),0))" t-as="l">\n                    <td t-translation="off">&amp;nbsp;</td>\n                    <td class="hidden"/>\n                    <td/>\n                    <td/>\n                    <td t-if="display_discount"/>\n                    <td/>\n                    <td/>\n                </tr>\n            </tbody>\n        </table>\n\n        <div id="total" class="row">\n            <div class="col-xs-4 pull-right">\n                <table class="table table-condensed">\n                    <tr class="border-black">\n                        <td><strong>Subtotal</strong></td>\n                        <td class="text-right">\n                            <span t-field="invoice.amount_untaxed" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>\n                        </td>\n                    </tr>\n                    <t t-foreach="invoice._get_tax_amount_by_group()" t-as="amount_by_group">\n                        <tr>\n                            <td><span t-esc="amount_by_group[0] if len(invoice.tax_line_ids) &gt; 1 else (invoice.tax_line_ids.tax_id.description or invoice.tax_line_ids.tax_id.name)"/></td>\n                            <td class="text-right">\n                                <span t-esc="amount_by_group[1]" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>\n                            </td>\n                        </tr>\n                    </t>\n                    <tr class="border-black">\n                        <td><strong>Total</strong></td>\n                        <td class="text-right">\n                             <span t-field="invoice.amount_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>\n                        </td>\n                    </tr>\n                </table>\n            </div>\n        </div>\n        <!-- DO NOT REMOVE THIS TABLE. MANDATORY IN SOME COUNTRIES -->\n        <div class="row" t-if="len(invoice.tax_line_ids) &gt; 0">\n            <div class="col-xs-6">\n                <table class="table table-condensed">\n                    <thead>\n                        <tr>\n                            <th>Tax</th>\n                            <th class="text-right">Base</th>\n                            <th class="text-right">Amount</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <tr t-foreach="invoice.tax_line_ids" t-as="t">\n                            <td><span t-field="t.tax_id.description"/></td>\n                            <td class="text-right">\n                                <span t-field="t.base" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>\n                            </td>\n                            <td class="text-right">\n                                <span t-field="t.amount" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>\n                            </td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n        <p t-if="invoice.comment">\n            <span t-field="invoice.comment"/>\n        </p>\n        <p t-if="invoice.payment_term_id">\n            <span t-field="invoice.payment_term_id.note"/>\n        </p>\n        <p t-if="invoice.fiscal_position_id.note">\n            <span t-field="invoice.fiscal_position_id.note"/>\n        </p>\n    </t>\n\n    	account/views/account_portal_templates.xml	\N	\N	2020-03-20 13:32:51.297728	2020-03-20 13:32:51.297728	primary	t	1	1
