681	stock.picking.internal.search	stock.picking	\N	16	search	<?xml version="1.0"?>\n<search string="Picking Lists">\n                    <field name="name" string="Picking List" filter_domain="['|',('name','ilike', self),('origin','ilike',self)]"/>\n                    <filter name="draft" string="Draft" domain="[('state','=','draft')]" help="Draft Moves"/>\n                    <filter name="available" string="Ready" domain="[('state','in',('assigned', 'partially_available'))]" help="Assigned Moves"/>\n                    <filter name="waiting" string="Waiting Availability" domain="[('state','in', ('confirmed', 'waiting'))]" help="Waiting Moves"/>\n                    <filter name="confirmed" string="Confirmed" domain="[('state','in', ('confirmed', 'waiting', 'assigned'))]" help="Confirmed Moves"/>\n                    <filter name="done" string="Done" domain="[('state','=','done')]" help="Pickings already processed"/>\n                    <separator/>\n                    <filter name="late" string="Late" domain="[('scheduled_date','&lt;', time.strftime('%Y-%m-%d %H:%M:%S')), ('state', 'in', ('assigned', 'waiting', 'confirmed'))]" help="Pickings that are late on scheduled time"/>\n                    <separator/>\n                    <filter name="backorder" string="Backorders" domain="[('backorder_id','!=', False)]" help="Remaining parts of picking partially processed"/>\n                    <separator/>\n                    <filter string="My Activities" name="activities_my" domain="[('activity_ids.user_id', '=', uid)]"/>\n                    <separator/>\n                    <filter string="Late Activities" name="activities_overdue" domain="[('activity_ids.date_deadline', '&lt;', context_today().strftime('%Y-%m-%d'))]" help="Show all records which has next action date is before today"/>\n                    <filter string="Today Activities" name="activities_today" domain="[('activity_ids.date_deadline', '=', context_today().strftime('%Y-%m-%d'))]"/>\n                    <filter string="Future Activities" name="activities_upcoming_all" domain="[('activity_ids.date_deadline', '&gt;', context_today().strftime('%Y-%m-%d'))                         ]"/>\n                    <field name="partner_id" filter_domain="[('partner_id','child_of',self)]"/>\n                    <field name="product_id"/>\n                    <field name="picking_type_id"/>\n                    <field name="group_id"/>\n                    <group expand="0" string="Group By">\n                        <filter string="Status" domain="[]" context="{'group_by':'state'}"/>\n                        <filter string="Order Date" domain="[]" context="{'group_by':'date'}"/>\n                        <filter string="Expected Date" domain="[]" context="{'group_by':'scheduled_date'}"/>\n                        <filter string="Origin" domain="[]" context="{'group_by':'origin'}"/>\n                        <filter name="picking_type" string="Operation Type" domain="[]" context="{'group_by':'picking_type_id'}"/>\n                        <filter string="Procurement Group" domain="[]" context="{'group_by':'group_id'}"/>\n                    </group>\n                </search>\n            	stock/views/stock_picking_views.xml	\N	\N	2020-03-20 13:33:59.668484	2020-03-20 13:33:59.668484	primary	t	1	1
