700	stock.quant.package.form	stock.quant.package	\N	10	form	<?xml version="1.0"?>\n<form string="Package">\n                <header>\n                    <button name="unpack" string="Unpack" type="object"/>\n                </header>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <button class="oe_stat_button" name="action_view_picking" string="Package Transfers" type="object" widget="statinfo" icon="fa-arrows-v"/>\n                    </div>\n                    <div class="oe_title">\n                        <label for="name" string="Package Reference" class="oe_edit_only"/>\n                        <h1><field name="name" class="oe_inline"/></h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name="company_id" groups="base.group_multi_company"/>\n                            <field name="owner_id" groups="stock.group_tracking_owner"/>\n                            <field name="location_id"/>\n                        </group>\n                    </group>\n                    <separator string="Ongoing Package Creation: Content" attrs="{'invisible': [('current_picking_id', '=', False)]}"/>\n                    <field name="current_picking_id" invisible="1"/>\n                    <field name="current_picking_move_line_ids" readonly="1" attrs="{'invisible': [('current_picking_id', '=', False)]}">\n                        <tree>\n                            <field name="product_id"/>\n                            <field name="lot_id" groups="stock.group_production_lot"/>\n                            <field name="qty_done" string="Quantity"/>\n                            <field name="product_uom_id" groups="product.group_uom"/>\n                        </tree>\n                    </field>\n                    <separator string="Content" attrs="{'invisible': [('current_picking_id', '=', True)]}"/>\n                    <field name="quant_ids" attrs="{'invisible': [('current_picking_id', '=', True)]}">\n                        <tree>\n                            <field name="product_id"/>\n                            <field name="lot_id" groups="stock.group_production_lot"/>\n                            <field name="quantity"/>\n                            <field name="product_uom_id" groups="product.group_uom"/>\n                        </tree>\n                    </field>\n                </sheet>\n            </form>\n        	stock/views/stock_quant_views.xml	\N	\N	2020-03-20 13:33:59.668484	2020-03-20 13:33:59.668484	primary	t	1	1
