567	sale.report.search	sale.report	\N	16	search	<?xml version="1.0"?>\n<search string="Sales Analysis">\n                <field name="date"/>\n                <filter string="This Year" name="year" invisible="1" domain="[('date','&lt;=', time.strftime('%Y-12-31')),('date','&gt;=',time.strftime('%Y-01-01'))]"/>\n                <filter name="Quotations" string="Quotations" domain="[('state','in', ('draft', 'sent'))]"/>\n                <filter name="Sales" string="Sales" domain="[('state','not in',('draft', 'cancel', 'sent'))]"/>\n                <separator/>\n                <field name="partner_id"/>\n                <field name="product_id"/>\n                <field name="user_id"/>\n                <group expand="0" string="Extended Filters">\n                    <field name="categ_id" filter_domain="[('categ_id', 'child_of', self)]"/>\n                    <field name="company_id" groups="base.group_multi_company"/>\n                </group>\n                <group expand="1" string="Group By">\n                    <filter string="Salesperson" name="User" context="{'group_by':'user_id'}"/>\n                    <filter string="Sales Channel" context="{'group_by':'team_id'}"/>\n                    <filter string="Partner's Country" name="country_id" context="{'group_by':'country_id'}"/>\n                    <filter string="Customer" name="Customer" context="{'group_by':'partner_id'}"/>\n                    <filter string="Product Category" name="Category" context="{'group_by':'categ_id'}"/>\n                    <filter name="status" string="Status" context="{'group_by':'state'}"/>\n                    <filter string="Company" groups="base.group_multi_company" context="{'group_by':'company_id'}"/>\n                    <separator/>\n                    <filter string="Order Month" context="{'group_by':'date:month'}" help="Ordered date of the sales order"/>\n                </group>\n            </search>\n        	sale/report/sale_report_views.xml	\N	\N	2020-03-20 13:33:12.577518	2020-03-20 13:33:12.577518	primary	t	1	1
568	report_saleorder_document	\N	sale.report_saleorder_document	16	qweb	<?xml version="1.0"?>\n<t t-name="sale.report_saleorder_document">\n    <t t-call="web.external_layout">\n        <t t-set="doc" t-value="doc.with_context(lang=doc.partner_id.lang)"/>\n        <div class="page">\n            <div class="oe_structure"/>\n            <div class="row">\n                <div class="col-xs-6">\n                    <t t-if="doc.partner_shipping_id == doc.partner_invoice_id                              and doc.partner_invoice_id != doc.partner_id                              or doc.partner_shipping_id != doc.partner_invoice_id">\n                        <strong t-if="doc.partner_shipping_id == doc.partner_invoice_id">Invoicing and shipping address:</strong>\n                        <strong t-if="doc.partner_shipping_id != doc.partner_invoice_id">Invoicing address:</strong>\n                        <div t-field="doc.partner_invoice_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        <div t-if="doc.partner_shipping_id != doc.partner_invoice_id" class="mt8">\n                            <strong>Shipping address:</strong>\n                            <div t-field="doc.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        </div>\n                    </t>\n                </div>\n                <div class="col-xs-5 col-xs-offset-1">\n                    <div t-field="doc.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                    <p t-if="doc.partner_id.vat"><t t-esc="doc.company_id.country_id.vat_label or 'TIN'"/>: <span t-field="doc.partner_id.vat"/></p>\n                </div>\n            </div>\n\n            <h2>\n                <t t-if="not (env.context.get('proforma', False) or is_pro_forma)">\n                    <span t-if="doc.state not in ['draft','sent']">Order # </span>\n                    <span t-if="doc.state in ['draft','sent']">Quotation # </span>\n                </t>\n                <t t-if="env.context.get('proforma', False) or is_pro_forma">\n                    <span>Pro-Forma Invoice # </span>\n                </t>\n                <span t-field="doc.name"/>\n            </h2>\n\n            <div class="row mt32 mb32" id="informations">\n                <div t-if="doc.client_order_ref" class="col-xs-3">\n                    <strong>Your Reference:</strong>\n                    <p t-field="doc.client_order_ref"/>\n                </div>\n                <div t-if="doc.confirmation_date and doc.state not in ['draft','sent']" class="col-xs-3">\n                    <strong>Date Ordered:</strong>\n                    <p t-field="doc.confirmation_date"/>\n                </div>\n                <div t-if="doc.date_order and doc.state in ['draft','sent']" class="col-xs-3">\n                    <strong>Quotation Date:</strong>\n                    <p t-field="doc.date_order"/>\n                </div>\n                <div t-if="doc.user_id.name" class="col-xs-3">\n                    <strong>Salesperson:</strong>\n                    <p t-field="doc.user_id"/>\n                </div>\n                <div name="payment_term" t-if="doc.payment_term_id" class="col-xs-3">\n                    <strong>Payment Terms:</strong>\n                    <p t-field="doc.payment_term_id"/>\n                </div>\n                <div t-if="doc.validity_date and doc.state in ['draft', 'sent']" class="col-xs-3">\n                    <strong>Expiration Date:</strong>\n                    <p t-field="doc.validity_date"/>\n                </div>\n            </div>\n\n            <!-- Is there a discount on at least one line? -->\n            <t t-set="display_discount" t-value="any([l.discount for l in doc.order_line])"/>\n\n            <t t-foreach="doc.order_lines_layouted()" t-as="page">\n                <table class="table table-condensed">\n                    <thead>\n                        <tr>\n                            <th>Description</th>\n                            <th class="text-right">Quantity</th>\n                            <th class="text-right">Unit Price</th>\n                            <th t-if="display_discount" class="text-right" groups="sale.group_discount_per_so_line">Disc.(%)</th>\n                            <th class="text-right">Taxes</th>\n                            <th class="text-right" groups="sale.group_show_price_subtotal">Amount</th>\n                            <th class="text-right price_tax_included" groups="sale.group_show_price_total">Total Price</th>\n                        </tr>\n                   </thead>\n                   <tbody class="sale_tbody">\n                        <t t-foreach="page" t-as="layout_category">\n\n                            <t t-if="layout_category_size &gt; 1 or page_size &gt; 1" groups="sale.group_sale_layout">\n                                <tr class="active">\n                                    <td colspan="7" style="font-weight: bold; border-bottom: 1px solid black;">&amp;bull;\n                                        <t t-esc="layout_category['name']"/>\n                                    </td>\n                                </tr>\n                            </t>\n\n                            <!-- Lines associated -->\n                            <t t-foreach="layout_category['lines']" t-as="l">\n                                <tr>\n                                    <td><span t-field="l.name"/></td>\n                                    <td class="text-right">\n                                        <span t-field="l.product_uom_qty"/>\n                                        <span t-field="l.product_uom" groups="product.group_uom"/>\n                                    </td>\n                                    <td class="text-right">\n                                        <span t-field="l.price_unit"/>\n                                    </td>\n                                    <td t-if="display_discount" class="text-right" groups="sale.group_discount_per_so_line">\n                                        <span t-field="l.discount"/>\n                                    </td>\n                                    <td class="text-right">\n                                        <span t-esc="', '.join(map(lambda x: (x.description or x.name), l.tax_id))"/>\n                                    </td>\n                                    <td class="text-right" groups="sale.group_show_price_subtotal">\n                                        <span t-field="l.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/>\n                                    </td>\n                                    <td class="text-right" groups="sale.group_show_price_total">\n                                        <span t-field="l.price_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/>\n                                    </td>\n                                </tr>\n                            </t>\n\n                            <t t-if="(layout_category_size &gt; 1 or page_size &gt; 1) and layout_category['subtotal']" groups="sale.group_sale_layout">\n                                <tr class="text-right">\n                                    <td colspan="6">\n                                        <strong>Subtotal: </strong>\n                                        <t t-set="subtotal" t-value="sum(line.price_subtotal for line in layout_category['lines'])"/>\n                                        <span t-esc="subtotal" t-options="{'widget': 'monetary', 'display_currency': doc.pricelist_id.currency_id}"/>\n                                    </td>\n                                </tr>\n                            </t>\n\n                        </t>\n                    </tbody>\n                </table>\n\n                <t t-if="page_index &lt; page_size - 1" groups="sale.group_sale_layout">\n                    <p style="page-break-before:always;"> </p>\n                </t>\n            </t>\n\n            <div class="clearfix">\n                <div class="row" name="total">\n                    <div class="col-xs-4 pull-right">\n                        <table class="table table-condensed" style="min-width: 200px;max-width: 350px;">\n                            <tr class="border-black" style="border-bottom:1px solid #dddddd;">\n                                <td><strong>Subtotal</strong></td>\n                                <td class="text-right">\n                                    <span t-field="doc.amount_untaxed" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/>\n                                </td>\n                            </tr>\n                            <t t-foreach="doc._get_tax_amount_by_group()" t-as="amount_by_group">\n                                <tr style="border-bottom:1px solid #dddddd;">\n                                    <t t-if="amount_by_group[3] == 1 and doc.amount_untaxed == amount_by_group[2]">\n                                        <td>\n                                            <span t-esc="amount_by_group[0]"/>\n                                            <span>&amp;nbsp;<span>on</span>&amp;nbsp;<t t-esc="amount_by_group[2]" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/></span>\n                                        </td>\n                                        <td class="text-right">\n                                            <span t-esc="amount_by_group[1]" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/>\n                                        </td>\n                                    </t>\n                                    <t t-else="">\n                                        <td>\n                                            <span t-esc="amount_by_group[0]"/>\n                                        </td>\n                                        <td class="text-right">\n                                            <span t-esc="amount_by_group[1]" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/>\n                                        </td>\n                                    </t>\n                                </tr>\n                            </t>\n                            <tr class="border-black">\n                                <td><strong>Total</strong></td>\n                                <td class="text-right">\n                                    <span t-field="doc.amount_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.pricelist_id.currency_id}"/>\n                                </td>\n                            </tr>\n                        </table>\n                    </div>\n                </div>\n            </div>\n\n            <p t-field="doc.note"/>\n            <p t-if="doc.payment_term_id.note">\n                <span t-field="doc.payment_term_id.note"/>\n            </p>\n            <p id="fiscal_position_remark" t-if="doc.fiscal_position_id and doc.fiscal_position_id.note">\n                <strong>Fiscal Position Remark:</strong>\n                <span t-field="doc.fiscal_position_id.note"/>\n            </p>\n            <div class="oe_structure"/>\n        </div>\n    </t>\n</t>\n\n\n	sale/report/sale_report_templates.xml	\N	\N	2020-03-20 13:33:12.577518	2020-03-20 13:33:12.577518	primary	t	1	1
569	report_saleorder	\N	sale.report_saleorder	16	qweb	<?xml version="1.0"?>\n<t t-name="sale.report_saleorder">\n    <t t-call="web.html_container">\n        <t t-foreach="docs" t-as="doc">\n            <t t-call="sale.report_saleorder_document" t-lang="doc.partner_id.lang"/>\n        </t>\n    </t>\n</t>\n\n	sale/report/sale_report_templates.xml	\N	\N	2020-03-20 13:33:12.577518	2020-03-20 13:33:12.577518	primary	t	1	1
570	report_saleorder_pro_forma	\N	sale.report_saleorder_pro_forma	16	qweb	<?xml version="1.0"?>\n<t t-name="sale.report_saleorder_pro_forma">\n    <t t-call="web.html_container">\n        <t t-set="is_pro_forma" t-value="True"/>\n        <t t-foreach="docs" t-as="doc">\n            <t t-call="sale.report_saleorder_document" t-lang="doc.partner_id.lang"/>\n        </t>\n    </t>\n</t>\n\n	sale/report/sale_report_templates.xml	\N	\N	2020-03-20 13:33:12.577518	2020-03-20 13:33:12.577518	primary	t	1	1
571	report_invoice_layouted	\N	sale.report_invoice_layouted	16	qweb	<?xml version="1.0"?>\n<data inherit_id="account.report_invoice_document">\n    <xpath expr="//table/tbody/tr/td[@id='subtotal']" position="attributes">\n        <attribute name="groups">!sale.group_show_price_total</attribute>\n    </xpath>\n    <xpath expr="//table/tbody/tr/td[@id='subtotal']" position="after">\n        <td class="text-right" groups="sale.group_show_price_total">\n            <span t-field="l.price_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n        </td>\n    </xpath>\n    <xpath expr="//table" position="attributes">\n        <attribute name="groups">!sale.group_sale_layout</attribute>\n    </xpath>\n    <xpath expr="//table" position="after">\n        <t groups="sale.group_sale_layout" t-foreach="o.order_lines_layouted()" t-as="page" name="lines_layouted">\n            <table class="table table-condensed">\n                <thead>\n                    <tr>\n                        <th>Description</th>\n                        <th class="text-right">Quantity</th>\n                        <th class="text-right">Unit Price</th>\n                        <th t-if="display_discount" class="text-right" groups="sale.group_discount_per_so_line">Disc.(%)</th>\n                        <th class="text-right">Taxes</th>\n                        <th class="text-right">Amount</th>\n                    </tr>\n                </thead>\n                <tbody class="invoice_tbody">\n                    <t t-foreach="page" t-as="layout_category">\n\n                        <t t-if="layout_category_size &gt; 1 or page_size &gt; 1" groups="sale.group_sale_layout">\n                            <tr class="active">\n                                <td colspan="7" style="font-weight: bold; border-bottom: 1px solid black;">&amp;bull;\n                                    <t t-esc="layout_category['name']"/>\n                                </td>\n                            </tr>\n                        </t>\n\n                        <!-- Lines associated -->\n                        <t t-foreach="layout_category['lines']" t-as="l">\n                            <tr>\n                                <td><span t-field="l.name"/></td>\n                                <td class="text-right">\n                                    <span t-field="l.quantity"/>\n                                    <span t-field="l.uom_id" groups="product.group_uom"/>\n                                </td>\n                                <td class="text-right">\n                                    <span t-field="l.price_unit"/>\n                                </td>\n                                <td t-if="display_discount" class="text-right" groups="sale.group_discount_per_so_line">\n                                    <span t-field="l.discount"/>\n                                </td>\n                                <td class="text-right">\n                                    <span t-esc="', '.join(map(lambda x: x.description or x.name, l.invoice_line_tax_ids))"/>\n                                </td>\n                                <td class="text-right">\n                                    <span t-field="l.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                </td>\n                                <td class="text-right" groups="sale.group_show_price_total">\n                                    <span t-field="l.price_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                                </td>\n                            </tr>\n                        </t>\n\n                        <t t-if="(layout_category_size &gt; 1 or page_size &gt; 1) and layout_category['subtotal']" groups="sale.group_sale_layout">\n                            <tr class="text-right">\n                                <td colspan="6">\n                                    <strong>Subtotal: </strong>\n                                    <t t-set="subtotal" t-value="sum(line.price_subtotal for line in layout_category['lines'])"/>\n                                    <span t-esc="subtotal" t-options="{'widget': 'monetary', 'display_currency': o.currency_id}"/>\n                                </td>\n                            </tr>\n                        </t>\n                    </t>\n                </tbody>\n            </table>\n\n            <t t-if="page_index &lt; page_size - 1" groups="sale.group_sale_layout">\n                <p style="page-break-before:always;"> </p>\n            </t>\n        </t>\n    </xpath>\n</data>\n\n    	sale/report/invoice_report_templates.xml	487	\N	2020-03-20 13:33:12.577518	2020-03-20 13:33:12.577518	extension	t	1	1
