582	sale.order.form	sale.order	\N	16	form	<?xml version="1.0"?>\n<form string="Sales Order" class="o_sale_order">\n                <header>\n                    <button name="action_quotation_send" string="Send by Email" type="object" states="draft" class="btn-primary"/>\n                    <button name="action_quotation_send" type="object" string="Send PRO-FORMA Invoice" groups="sale.group_proforma_sales" class="btn-primary" attrs="{'invisible': ['|', ('state', '!=', 'draft'), ('invoice_count','&gt;=',1)]}" context="{'proforma': True}"/>\n                    <button name="print_quotation" string="Print" type="object" states="draft" class="btn-primary o_sale_print"/>\n                    <button name="action_confirm" id="action_confirm" string="Confirm Sale" class="btn-primary" type="object" attrs="{'invisible': [('state', 'not in', ['sent'])]}"/>\n                    <button name="action_confirm" string="Confirm Sale" type="object" attrs="{'invisible': [('state', 'not in', ['draft'])]}"/>\n                    <button name="action_quotation_send" type="object" string="Send PRO-FORMA Invoice" groups="sale.group_proforma_sales" attrs="{'invisible': ['|', ('state', '=', 'draft'), ('invoice_count','&gt;=',1)]}" context="{'proforma': True}"/>\n                    <button name="print_quotation" string="Print" type="object" states="sent,sale" class="o_sale_print"/>\n                    <button name="action_quotation_send" string="Send by Email" type="object" states="sent,sale"/>\n                    <button name="action_cancel" states="draft,sent,sale" type="object" string="Cancel"/>\n                    <button name="action_draft" states="cancel" type="object" string="Set to Quotation"/>\n                    <button name="action_done" type="object" string="Lock" states="sale" help="If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver."/>\n                    <button name="action_unlock" type="object" string="Unlock" states="done" groups="sales_team.group_sale_manager"/>\n                    <field name="state" widget="statusbar" statusbar_visible="draft,sent,sale"/>\n                </header>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <button name="action_view_invoice" type="object" class="oe_stat_button" icon="fa-pencil-square-o" attrs="{'invisible': [('invoice_count', '=', 0)]}">\n                            <field name="invoice_count" widget="statinfo" string="Invoices"/>\n                        </button>\n                    </div>\n                    <div class="oe_title">\n                        <h1>\n                            <field name="name" readonly="1"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name="partner_id" domain="[('customer','=',True)]" context="{'search_default_customer':1, 'show_address': 1}" options="{&quot;always_reload&quot;: True}"/>\n                            <field name="partner_invoice_id" groups="sale.group_delivery_invoice_address" context="{'default_type':'invoice'}" options="{&quot;always_reload&quot;: True}"/>\n                            <field name="partner_shipping_id" groups="sale.group_delivery_invoice_address" context="{'default_type':'delivery'}" options="{&quot;always_reload&quot;: True}"/>\n                        </group>\n                        <group>\n                            <field name="validity_date" attrs="{'invisible': [('state', 'in', ['sale', 'done'])]}"/>\n                            <field name="confirmation_date" attrs="{'invisible': [('state', 'in', ['draft', 'sent', 'cancel'])]}"/>\n                            <field name="pricelist_id" groups="product.group_sale_pricelist"/>\n                            <field name="currency_id" invisible="1"/>\n                            <field name="payment_term_id" options="{'no_create': True}"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string="Order Lines">\n                            <field name="order_line" mode="tree,kanban" attrs="{'readonly': [('state', 'in', ('done','cancel'))]}">\n                                <form string="Sales Order Lines">\n                                    <group>\n                                        <group>\n                                            <field name="product_updatable" invisible="1"/>\n                                            <field name="product_id" context="{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'company_id': parent.company_id}" attrs="{'readonly': [('product_updatable', '=', False)]}" force_save="1"/>\n                                            <field name="layout_category_id" groups="sale.group_sale_layout"/>\n                                            <field name="invoice_status" invisible="1"/>\n                                            <field name="qty_to_invoice" invisible="1"/>\n                                            <field name="qty_delivered_updateable" invisible="1"/>\n                                            <field name="price_total" invisible="1"/>\n                                            <field name="price_tax" invisible="1"/>\n                                            <field name="price_subtotal" invisible="1"/>\n                                            <label for="product_uom_qty" string="Ordered Quantity"/>\n                                            <div>\n                                                <field context="{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'uom_qty_change':True, 'company_id': parent.company_id}" name="product_uom_qty" class="oe_inline"/>\n                                                <field name="product_uom" groups="product.group_uom" class="oe_inline oe_no_button" force_save="1" attrs="{'readonly': [('state', 'in', ('sale','done', 'cancel'))]}"/>\n                                            </div>\n                                            <label for="qty_delivered" string="Delivered Quantity" attrs="{'invisible': [('parent.state', 'not in', ['sale', 'done'])]}"/>\n                                            <div attrs="{'invisible': [('parent.state', 'not in', ['sale', 'done'])]}">\n                                                <field name="qty_delivered" attrs="{'readonly': [('qty_delivered_updateable', '=', False)]}"/>\n                                            </div>\n                                            <label for="qty_invoiced" string="Invoiced Quantity" attrs="{'invisible': [('parent.state', 'not in', ['sale', 'done'])]}"/>\n                                            <div attrs="{'invisible': [('parent.state', 'not in', ['sale', 'done'])]}">\n                                                <field name="qty_invoiced" attrs="{'invisible': [('parent.state', 'not in', ['sale', 'done'])]}"/>\n                                            </div>\n                                            <field name="price_unit"/>\n                                            <label for="discount" groups="sale.group_discount_per_so_line"/>\n                                            <div name="discount" groups="sale.group_discount_per_so_line">\n                                                <field name="discount" class="oe_inline"/> %\n                                            </div>\n                                        </group>\n                                        <group>\n                                            <field name="tax_id" widget="many2many_tags" options="{'no_create': True}" domain="[('type_tax_use','=','sale'),('company_id','=',parent.company_id)]" attrs="{'readonly': [('qty_invoiced', '&gt;', 0)]}"/>\n                                            <label for="customer_lead"/>\n                                            <div>\n                                                <field name="customer_lead" class="oe_inline"/> days\n                                            </div>\n                                            <label for="analytic_tag_ids" groups="analytic.group_analytic_accounting"/>\n                                            <div>\n                                                <field name="analytic_tag_ids" widget="many2many_tags" groups="analytic.group_analytic_accounting" options="{'color_field': 'color'}"/>\n                                            </div>\n                                        </group>\n                                    </group>\n                                    <label for="name"/>\n                                    <field name="name"/>\n                                    <div groups="base.group_no_one">\n                                        <label for="invoice_lines"/>\n                                        <field name="invoice_lines"/>\n                                    </div>\n                                    <field name="state" invisible="1"/>\n                                </form>\n                                <tree string="Sales Order Lines" editable="bottom" decoration-info="invoice_status=='to invoice'">\n                                    <field name="sequence" widget="handle"/>\n                                    <field name="product_updatable" invisible="1"/>\n                                    <field name="product_id" attrs="{'readonly': [('product_updatable', '=', False)]}" force_save="1" context="{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'company_id': parent.company_id}"/>\n                                    <field name="layout_category_id" groups="sale.group_sale_layout"/>\n                                    <field name="name"/>\n                                    <field name="product_uom_qty" string="Ordered Qty" context="{'partner_id':parent.partner_id, 'quantity':product_uom_qty, 'pricelist':parent.pricelist_id, 'uom':product_uom, 'company_id': parent.company_id}"/>\n                                    <field name="qty_delivered" attrs="{'column_invisible': [('parent.state', 'not in', ['sale', 'done'])], 'readonly': [('qty_delivered_updateable', '=', False)]}"/>\n                                    <field name="qty_invoiced" attrs="{'column_invisible': [('parent.state', 'not in', ['sale', 'done'])]}"/>\n                                    <field name="qty_to_invoice" invisible="1"/>\n                                    <field name="product_uom" force_save="1" attrs="{'readonly': [('state', 'in', ('sale','done', 'cancel'))]}" context="{'company_id': parent.company_id}" groups="product.group_uom" options="{&quot;no_open&quot;: True}"/>\n                                    <field name="analytic_tag_ids" groups="analytic.group_analytic_accounting" widget="many2many_tags" options="{'color_field': 'color'}"/>\n                                    <field name="price_unit" attrs="{'readonly': [('qty_invoiced', '&gt;', 0)]}"/>\n                                    <field name="tax_id" widget="many2many_tags" options="{'no_create': True}" domain="[('type_tax_use','=','sale'),('company_id','=',parent.company_id)]" attrs="{'readonly': [('qty_invoiced', '&gt;', 0)]}"/>\n                                    <field name="discount" groups="sale.group_discount_per_so_line"/>\n                                    <field name="price_subtotal" widget="monetary" groups="sale.group_show_price_subtotal"/>\n                                    <field name="price_total" widget="monetary" groups="sale.group_show_price_total"/>\n                                    <field name="qty_delivered_updateable" invisible="1"/>\n                                    <field name="state" invisible="1"/>\n                                    <field name="invoice_status" invisible="1"/>\n                                    <field name="customer_lead" invisible="1"/>\n                                    <field name="currency_id" invisible="1"/>\n                                    <field name="price_tax" invisible="1"/>\n                                </tree>\n                                <kanban class="o_kanban_mobile">\n                                    <field name="product_id"/>\n                                    <field name="product_uom_qty"/>\n                                    <field name="product_uom" groups="product.group_uom"/>\n                                    <field name="price_subtotal"/>\n                                    <field name="price_tax" invisible="1"/>\n                                    <field name="price_total" invisible="1"/>\n                                    <field name="price_unit"/>\n                                    <templates>\n                                        <t t-name="kanban-box">\n                                            <div t-attf-class="oe_kanban_card oe_kanban_global_click">\n                                                <div class="row">\n                                                    <div class="col-xs-8">\n                                                        <strong><span><t t-esc="record.product_id.value"/></span></strong>\n                                                    </div>\n                                                    <div class="col-xs-4">\n                                                        <strong><span class="pull-right text-right">\n                                                        <t t-esc="record.price_subtotal.value"/></span></strong>\n                                                    </div>\n                                                </div>\n                                                <div class="row">\n                                                    <div class="col-xs-12 text-muted">\n                                                        <span>Quantity: <t t-esc="record.product_uom_qty.value"/> <t t-esc="record.product_uom.value"/></span>\n                                                    </div>\n                                                </div>\n                                                <div class="row">\n                                                    <div class="col-xs-12 text-muted">\n                                                        <span>Unit Price: <t t-esc="record.price_unit.value"/></span>\n                                                    </div>\n                                                </div>\n                                            </div>\n                                            <hr/>\n                                        </t>\n                                    </templates>\n                                </kanban>\n                            </field>\n                            <group class="oe_subtotal_footer oe_right" colspan="2" name="sale_total">\n                                <field name="amount_untaxed" widget="monetary" options="{'currency_field': 'currency_id'}"/>\n                                <field name="amount_tax" widget="monetary" options="{'currency_field': 'currency_id'}"/>\n                                <div class="oe_subtotal_footer_separator oe_inline o_td_label">\n                                    <label for="amount_total"/>\n                                </div>\n                                <field name="amount_total" nolabel="1" class="oe_subtotal_footer_separator" widget="monetary" options="{'currency_field': 'currency_id'}"/>\n                            </group>\n                            <field name="note" class="oe_inline" placeholder="Setup default terms and conditions in your sales settings ..."/>\n                            <div class="oe_clear"/>\n                        </page>\n                        <page string="Other Informati