816	Portal: My Purchase Orders	\N	purchase.portal_my_purchase_orders	16	qweb	<?xml version="1.0"?>\n<t name="Portal: My Purchase Orders" t-name="purchase.portal_my_purchase_orders">\n    <t t-call="portal.portal_layout">\n      <h3>Purchase Orders\n        <t t-call="portal.portal_searchbar"/>\n      </h3>\n      <div t-if="orders" class="panel panel-default">\n      <div class="table-responsive"><table class="table table-hover o_portal_my_doc_table">\n        <thead>\n          <tr class="active">\n            <th>Purchase Orders #</th>\n            <th>Order Date</th>\n            <th/>\n            <th>Total</th>\n          </tr>\n        </thead>\n        <t t-foreach="orders" t-as="order">\n          <tr>\n            <td>\n              <a t-attf-href="/my/purchase/#{order.id}?#{keep_query()}"><t t-esc="order.name"/></a>\n            </td>\n            <td><span t-field="order.date_order"/></td>\n            <td>\n              <t t-if="order.state == 'cancel'">\n                <span class="label label-default"><i class="fa fa-fw fa-remove"/> Cancelled</span>\n              </t>\n            </td>\n            <td><span t-field="order.amount_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/>\n            </td>\n          </tr>\n        </t>\n      </table></div>\n      <div t-if="pager" class="o_portal_pager text-center">\n        <t t-call="portal.pager"/>\n      </div>\n      </div>\n    </t>\n  </t>\n\n  	purchase/views/portal_templates.xml	\N	\N	2020-03-20 13:34:30.363696	2020-03-20 13:34:30.363696	primary	t	1	1
817	Portal: My Purchase Order	\N	purchase.portal_my_purchase_order	16	qweb	<?xml version="1.0"?>\n<t name="Portal: My Purchase Order" t-name="purchase.portal_my_purchase_order">\n    <t t-call="portal.portal_layout">\n      <t t-set="purchase_order" t-value="order"/>\n      <div id="optional_placeholder"/>\n      <div class="container">\n          <div class="panel panel-default">\n            <div class="panel-heading">\n              <div class="row">\n                <div class="col-md-12">\n                  <h4>\n                    <t t-call="portal.record_pager"/>\n                    Purchase Order\n                    <span t-esc="order.name"/>\n                  </h4>\n                </div>\n              </div>\n            </div>\n            <div class="panel-body">\n              <div class="mb8">\n                  <strong>Date:</strong> <span t-field="order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n              </div>\n              <div class="row">\n                <div class="col-md-6">\n                  <strong>Product</strong>\n                </div>\n                <div class="col-md-2 text-right">\n                  <strong>Unit Price</strong>\n                </div>\n                <div class="col-md-2 text-right">\n                  <strong>Quantity</strong>\n                </div>\n                <div class="col-md-2 text-right">\n                  <strong>Subtotal</strong>\n                </div>\n              </div>\n              <t t-foreach="order.order_line" t-as="ol">\n                <div class="row purchases_vertical_align">\n                  <div class="col-md-1 text-center">\n                      <img t-att-src="'/web/image/purchase.order.line/%s/product_image/48x48' % ol.id"/>\n                  </div>\n                  <div id="product_name" class="col-md-5">\n                    <span t-esc="ol.product_id.name"/>\n                  </div>\n                  <div class="col-md-2 text-right">\n                    <span t-field="ol.price_unit" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/>\n                  </div>\n                  <div class="col-md-2 text-right">\n                      <span t-esc="ol.product_qty"/>\n                  </div>\n                  <div class="col-md-2 text-right">\n                    <span t-field="ol.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/>\n                  </div>\n                </div>\n              </t>\n\n              <hr/>\n\n              <div class="row">\n                <div class="col-md-12 text-right">\n                  <div class="row">\n                    <div class="col-md-10 text-right">\n                      Untaxed Amount:\n                    </div>\n                    <div class="col-md-2 text-right">\n                      <span t-field="order.amount_untaxed" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/>\n                    </div>\n                  </div>\n                  <div class="row">\n                    <div class="col-md-10 text-right">\n                      Taxes:\n                    </div>\n                    <div class="col-md-2 text-right">\n                      <span t-field="order.amount_tax" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/>\n                    </div>\n                  </div>\n                  <div class="row">\n                    <div class="col-md-10 text-right">\n                      <strong>Total:</strong>\n                    </div>\n                    <div class="col-md-2 text-right">\n                      <strong><span t-field="order.amount_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/></strong>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n      </div>\n      <div class="oe_structure mb32"/>\n    </t>\n  </t>\n\n	purchase/views/portal_templates.xml	\N	\N	2020-03-20 13:34:30.363696	2020-03-20 13:34:30.363696	primary	t	1	1
818	report_purchaseorder_document	\N	purchase.report_purchaseorder_document	16	qweb	<?xml version="1.0"?>\n<t t-name="purchase.report_purchaseorder_document">\n    <t t-call="web.external_layout">\n        <t t-set="o" t-value="o.with_context(lang=o.partner_id.lang)"/>\n        <div class="page">\n            <div class="oe_structure"/>\n            <div class="row">\n                <div class="col-xs-6">\n                    <strong>Shipping address:</strong>\n                    <div t-if="o.dest_address_id">\n                        <div t-field="o.dest_address_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                    </div>\n\n                    <div t-if="not o.dest_address_id and o.picking_type_id and o.picking_type_id.warehouse_id">\n                        <span t-field="o.picking_type_id.warehouse_id.name"/>\n                        <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                    </div>\n                </div>\n                <div class="col-xs-5 col-xs-offset-1">\n                    <div t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        <p t-if="o.partner_id.vat"><t t-esc="o.company_id.country_id.vat_label or 'TIN'"/>: <span t-field="o.partner_id.vat"/></p>\n                </div>\n            </div>\n\n            <h2 t-if="o.state != 'draft'">Purchase Order Confirmation #<span t-field="o.name"/></h2>\n            <h2 t-if="o.state == 'draft'">Request for Quotation #<span t-field="o.name"/></h2>\n\n            <div class="row mt32 mb32">\n                <div t-if="o.name" class="col-xs-3">\n                    <strong>Our Order Reference:</strong>\n                    <p t-field="o.name"/>\n                </div>\n                <div t-if="o.partner_ref" class="col-xs-3">\n                    <strong>Your Order Reference:</strong>\n                    <p t-field="o.partner_ref"/>\n                </div>\n                <div t-if="o.date_order" class="col-xs-3">\n                    <strong>Order Date:</strong>\n                    <p t-field="o.date_order"/>\n                </div>\n            </div>\n\n            <table class="table table-condensed">\n                <thead>\n                    <tr>\n                        <th><strong>Description</strong></th>\n                        <th><strong>Taxes</strong></th>\n                        <th class="text-center"><strong>Date Req.</strong></th>\n                        <th class="text-right"><strong>Qty</strong></th>\n                        <th class="text-right"><strong>Unit Price</strong></th>\n                        <th class="text-right"><strong>Amount</strong></th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr t-foreach="o.order_line" t-as="line">\n                        <td>\n                            <span t-field="line.name"/>\n                        </td>\n                        <td>\n                            <span t-esc="', '.join(map(lambda x: x.name, line.taxes_id))"/>\n                        </td>\n                        <td class="text-center">\n                            <span t-field="line.date_planned"/>\n                        </td>\n                        <td class="text-right">\n                            <span t-field="line.product_qty"/>\n                            <span t-field="line.product_uom.name" groups="product.group_uom"/>\n                        </td>\n                        <td class="text-right">\n                            <span t-field="line.price_unit"/>\n                        </td>\n                        <td class="text-right">\n                            <span t-field="line.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n\n            <div class="row">\n                <div class="col-xs-4 pull-right">\n                    <table class="table table-condensed">\n                        <tr class="border-black">\n                            <td><strong>Subtotal</strong></td>\n                            <td class="text-right">\n                                <span t-field="o.amount_untaxed" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                            </td>\n                        </tr>\n                        <tr>\n                            <td>Taxes</td>\n                            <td class="text-right">\n                                <span t-field="o.amount_tax" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                            </td>\n                        </tr>\n                        <tr class="border-black">\n                            <td><strong>Total</strong></td>\n                            <td class="text-right">\n                                <span t-field="o.amount_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>\n                            </td>\n                        </tr>\n                    </table>\n                </div>\n            </div>\n\n            <p t-field="o.notes"/>\n            <div class="oe_structure"/>\n        </div>\n    </t>\n</t>\n\n	purchase/report/purchase_order_templates.xml	\N	\N	2020-03-20 13:34:30.363696	2020-03-20 13:34:30.363696	primary	t	1	1
