       odoo.define('web.web_client', function (require) {\n                var WebClient = require('web.AbstractWebClient');\n                var web_client = new WebClient();\n\n                web_client._title_changed = function() {};\n                web_client.show_application = function() {\n                    return web_client.action_manager.do_action("pos.ui");\n                };\n\n                $(function () {\n                    web_client.setElement($(document.body));\n                    web_client.start();\n                });\n                return web_client;\n            });\n        </script>\n    </head>\n    <body>\n        <div class="o_main_content"/>\n    </body>\n</html>\n</t>\n\n	point_of_sale/views/pos_templates.xml	\N	\N	2020-03-20 13:35:44.413185	2020-03-20 13:35:44.413185	primary	t	1	1
