864	pos.session.form.view	pos.session	\N	16	form	<?xml version="1.0"?>\n<form string="Point of Sale Session" create="0">\n                <header>\n                    <button name="action_pos_session_open" type="object" string="Open Session" attrs="{'invisible' : ['|', ('cash_control', '=', False), ('state', '!=', 'opening_control')]}" class="oe_highlight"/>\n                    <button name="open_frontend_cb" type="object" string="Continue Selling" states="opened" class="oe_highlight"/>\n                    <button name="action_pos_session_closing_control" type="object" string="End of Session" attrs="{'invisible' : ['|', ('cash_control', '=', False),('state', '!=', 'opened')]}" class="oe_highlight"/>\n                    <button name="action_pos_session_closing_control" type="object" string="Validate Closing &amp; Post Entries" attrs="{'invisible' : ['|', ('cash_control', '=', True),('state', '!=', 'opened')]}" class="oe_highlight"/>\n                    <button name="action_pos_session_validate" type="object" string="Validate Closing &amp; Post Entries" states="closing_control" class="oe_highlight"/>\n                    \n                    <field name="state" widget="statusbar" statusbar_visible="opening_control,opened,closing_control,closed" nolabel="1"/>\n                    \n                </header>\n                <sheet>\n                    <field name="cash_register_id" invisible="1"/>\n                    <div class="oe_button_box" name="button_box">\n                        <button class="oe_stat_button" name="329" type="action" icon="fa-level-down" attrs="{'invisible': ['|', ('cash_control', '=', False), ('state', 'not in', ['opened', 'closing_control'])]}">\n                            <div class="o_field_widget o_stat_info">\n                                <span class="o_stat_text">Put</span>\n                                <span class="o_stat_text">Money In</span>\n                            </div>\n                        </button>\n       