879	report_statement	\N	point_of_sale.report_statement	16	qweb	<?xml version="1.0"?>\n<t t-name="point_of_sale.report_statement">\n    <t t-call="web.html_container">\n        <t t-foreach="docs" t-as="o">\n            <t t-call="web.internal_layout">\n                <div class="page">\n                    <h2>Statement</h2>\n\n                    <div class="row">\n                        <div class="col-xs-3">\n                            <strong>Statement Name</strong>:<br/>\n                            <span t-field="o.name"/>\n                        </div>\n                        <div class="col-xs-3">\n                            <strong>Journal</strong>:<br/>\n                            <span t-field="o.journal_id"/>\n                        </div>\n                        <div class="col-xs-3">\n                            <strong>Company</strong>:<br/>\n                            <span t-field="o.company_id"/>                            \n                        </div>\n                        <div class="col-xs-3">\n                            <strong>User</strong>:<br/>\n                            <span t-field="o.user_id"/>                            \n                        </div>\n                    </div>\n\n                    <div class="row mb32">\n                        <div class="col-xs-3">\n                            <strong>Opening Date</strong>:<br/>\n                            <span t-field="o.date"/>\n                        </div>\n                        <div class="col-xs-3">\n                            <strong>Starting Balance</strong>:<br/>\n                            <span t-field="o.balance_start" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: res_company.currency_id}"/>\n                        </div>\n                        <div class="col-xs-3">\n                            <strong>Ending Balance</strong>:<br/>\n                            <span t-field="o.balance_end_real" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: res_company.currency_id}"/>\n                        </div>\n                    </div>\n\n                    <table class="table table-condensed">\n                        <thead>\n                            <tr>\n                                <th>Name</th>\n                                <th>Partner</th>\n                                <th class="text-right">Amount</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr t-foreach="o.line_ids" t-as="line">\n                                <td><span t-field="line.name"/></td>\n                                <td><span t-esc="line.partner_id.name"/></td>\n                                <td class="text-right">\n                                    <span t-field="line.amount" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: res_company.currency_id}"/>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>           \n\n                    <div class="row">\n                        <div class="col-xs-4 pull-right">\n                            <table class="table table-condensed">\n                                <tr class="border-black">\n                                    <td><strong>Total</strong></td>\n                                    <td class="text-right"><span t-esc="sum([line.amount for line in o.line_ids])" t-options="{'widget': 'monetary', 'display_currency': res_company.currency_id}"/></td>\n                                </tr>\n                            </table>\n                        </div>\n                    </div>\n                </div>\n            </t>\n        </t>\n    </t>\n</t>\n	point_of_sale/views/report_statement.xml	\N	\N	2020-03-20 13:35:44.413185	2020-03-20 13:35:44.413185	primary	t	1	1
